var e={ENAV:{nome:`ENAV`,cor:`#1E40AF`},CESPE:{nome:`CESPE/Cebraspe`,cor:`#991B1B`},FCC:{nome:`FCC`,cor:`#166534`},VUNESP:{nome:`VUNESP`,cor:`#7C2D12`},AVAMEC:{nome:`AVAMEC`,cor:`#581C87`},CRMV:{nome:`CRMV`,cor:`#0E7490`},UFMG:{nome:`UFMG`,cor:`#4338CA`},UNESP:{nome:`UNESP`,cor:`#B45309`},USP:{nome:`USP`,cor:`#0F766E`},UFRRJ:{nome:`UFRRJ`,cor:`#BE185D`},MAPA:{nome:`MAPA`,cor:`#374151`}},t={concurso:{nome:`Concurso Público`,cor:`#1E40AF`},residencia:{nome:`Residência Veterinária`,cor:`#9333EA`},enav:{nome:`ENAV`,cor:`#DC2626`},crmv:{nome:`Exame CRMV`,cor:`#0D9488`},pos:{nome:`Pós-Graduação`,cor:`#D97706`}},n={conceitos_necropsia:{nome:`Conceitos de Necropsia`,eixo:`conceitos`},tecnica_necropsia_bovina:{nome:`Técnica de Necropsia Bovina`,eixo:`tecnica`},tecnica_necropsia_equina:{nome:`Técnica de Necropsia Equina`,eixo:`tecnica`},tecnica_necropsia_canina_felina:{nome:`Técnica de Necropsia Canina e Felina`,eixo:`tecnica`},tecnica_necropsia_suina:{nome:`Técnica de Necropsia Suína`,eixo:`tecnica`},tecnica_necropsia_aviar:{nome:`Técnica de Necropsia Aviar`,eixo:`tecnica`},tecnica_necropsia_peixes:{nome:`Técnica de Necropsia de Peixes`,eixo:`tecnica`},processos_pre_mortem:{nome:`Processos Pré-Mortem`,eixo:`processos`},processos_post_mortem:{nome:`Processos Pós-Mortem`,eixo:`processos`},coleta_preservacao_material:{nome:`Coleta e Preservação de Material`,eixo:`coleta`},diagnostico_necroscopico:{nome:`Diagnóstico Necroscópico`,eixo:`diagnostico`},biosseguranca_necropsia:{nome:`Biossegurança na Necropsia`,eixo:`biosseguranca`}},r=[{id:`necr-001`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`conceitos_necropsia`,subtopico:`Definição e finalidades da necropsia`,dificuldade:`facil`,enunciado:`A necropsia veterinária pode ser definida como:`,alternativas:[`O exame externo e interno do cadáver animal com a finalidade de determinar a causa mortis, identificar lesões e contribuir para o diagnóstico de doenças.`,`Apenas o exame externo do cadáver para fins legais.`,`O procedimento cirúrgico realizado em animais vivos para coleta de biópsias.`,`O exame laboratorial de amostras de sangue coletadas post mortem.`,`A inspeção visual de carcaças no abate industrial.`],resposta_correta:`A`,explicacao:`A necropsia (do latim necro = morte, opsia = ver) é o exame minucioso do cadáver, incluindo exame externo e interno, visando determinar a causa da morte, identificar lesões macroscópicas, coletar material para exames complementares e contribuir para o diagnóstico epidemiológico.`},{id:`necr-002`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`conceitos_necropsia`,subtopico:`Indicações para necropsia`,dificuldade:`medio`,enunciado:`Julgue o item a seguir sobre indicações para realização de necropsia:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A necropsia deve ser indicada em casos de morte súbita, morte sem diagnóstico clínico definido, doenças de notificação obrigatória, surtos epidemiológicos, suspeita de intoxicação, morte em animais de produção com valor zootécnico e em situações de interesse legal ou policial.`,explicacao:`As indicações para necropsia são amplas e incluem qualquer morte em que o conhecimento da causa possa ter valor clínico, epidemiológico, legal ou científico. A necropsia é especialmente importante em mortes súbitas, surtos e doenças de notificação compulsória.`},{id:`necr-003`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário MAPA 2023`,tipo:`concurso`,topico:`conceitos_necropsia`,subtopico:`Legislação sobre necropsia`,dificuldade:`dificil`,enunciado:`Sobre a responsabilidade legal do médico veterinário na realização de necropsia, é correto afirmar:`,alternativas:[`O médico veterinário tem a obrigação ética e legal de realizar necropsia quando solicitado, podendo se recusar apenas quando houver risco à sua integridade física ou quando o procedimento não for tecnicamente viável.`,`A necropsia só pode ser realizada com autorização judicial prévia em todos os casos.`,`O médico veterinário não possui responsabilidade legal sobre os achados de necropsia, sendo esta uma atribuição exclusiva do médico legista.`,`A necropsia veterinária é regulamentada apenas pelo Código de Ética Médica, sem respaldo em legislação específica.`,`O profissional pode realizar necropsia sem registro detalhado dos achados, desde que emita atestado de óbito.`],resposta_correta:`A`,explicacao:`O médico veterinário possui responsabilidade ética e legal na realização de necropsias, conforme o Código de Ética Veterinária (Resolução CFMV nº 1.199/2016) e a Lei Federal nº 5.517/1968. O profissional deve documentar todos os achados e pode se recusar apenas por justificativa técnica ou segurança.`},{id:`necr-004`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso Veterinário 2021`,tipo:`concurso`,topico:`conceitos_necropsia`,subtopico:`Tipos de necropsia`,dificuldade:`facil`,enunciado:`Quanto à abordagem, a necropsia pode ser classificada em:`,alternativas:[`Necropsia parcial (regional) e necropsia completa (sistemática).`,`Necropsia clínica e necropsia cirúrgica.`,`Necropsia de campo e necropsia de laboratório.`,`Necropsia simples e necropsia composta.`,`Necropsia superficial e necropsia profunda.`],resposta_correta:`A`,explicacao:`A necropsia pode ser parcial (quando se examina apenas uma região ou sistema de órgãos, como em inspeção de abatedouro) ou completa (quando se examina sistematicamente todos os órgãos e cavidades do cadáver). A necropsia completa é a mais recomendada para diagnóstico.`},{id:`necr-005`,banca:`UNESP`,ano:2022,prova:`UNESP — Professor Veterinária 2022`,tipo:`concurso`,topico:`conceitos_necropsia`,subtopico:`Equipamentos para necropsia`,dificuldade:`medio`,enunciado:`Para a realização de uma necropsia completa em campo, o equipamento básico indispensável inclui:`,alternativas:[`Facas de necropsia, tesoura de ponta romba, tesoura de ponta aguda, bisturi, serrote ósseo, pinça anatômica, pinça hemostática, régua, luvas descartáveis e sacos para coleta de material.`,`Apenas bisturi e serrote ósseo.`,`Microscópio ótico e lâminas de histologia.`,`Aparelho de raio-X e equipamento de ultrassonografia.`,`Termômetro digital e esfigmomanômetro.`],resposta_correta:`A`,explicacao:`O instrumental básico para necropsia em campo inclui facas de diferentes tamanhos, tesouras (reta e curva, de ponta romba e aguda), bisturi, serrote ósseo, pinças anatômicas e hemostáticas, sonda, régua, além de EPIs e materiais de coleta. O microscópio e equipamentos de imagem não fazem parte do kit de campo.`},{id:`necr-006`,banca:`ENAV`,ano:2024,prova:`ENAV — Residência 2024`,tipo:`residencia`,topico:`conceitos_necropsia`,subtopico:`Momento ideal para necropsia`,dificuldade:`medio`,enunciado:`Sobre o momento ideal para realização de necropsia, assinale a alternativa correta:`,alternativas:[`A necropsia deve ser realizada o mais breve possível após a morte, preferencialmente nas primeiras 6 horas, antes que alterações autolíticas e de putrefação comprometam a interpretação das lesões.`,`O ideal é aguardar pelo menos 24 horas após a morte para que os tecidos estejam mais amaciados e facilitem o corte.`,`O momento da necropsia é irrelevante, pois as lesões permanecem inalteradas por até uma semana.`,`A necropsia só pode ser realizada após o período de rigor mortis, ou seja, após 48 horas.`,`Deve-se aguardar a completa putrefação para melhor visualização das estruturas internas.`],resposta_correta:`A`,explicacao:`A necropsia deve ser realizada o mais precocemente possível após a morte. Após 6 horas em temperatura ambiente, processos autolíticos (degradação celular endógena) e putrefação (degradação bacteriana) começam a comprometer a arquitetura tecidual e a interpretação das lesões.`},{id:`necr-007`,banca:`UFMG`,ano:2020,prova:`UFMG — Concurso Veterinário 2020`,tipo:`concurso`,topico:`conceitos_necropsia`,subtopico:`Finalidades da necropsia`,dificuldade:`facil`,enunciado:`Assinale a alternativa que NÃO constitui finalidade da necropsia veterinária:`,alternativas:[`Realizar tratamento clínico do animal antes do óbito.`,`Determinar a causa mortis.`,`Contribuir para o diagnóstico de doenças emergentes.`,`Fornecer subsídios para programas de vigilância epidemiológica.`,`Auxiliar em perícias judiciais e investigações legais.`],resposta_correta:`A`,explicacao:`A necropsia é um procedimento post mortem e, portanto, não tem finalidade terapêutica. Suas principais finalidades incluem determinar a causa da morte, identificar lesões e doenças, contribuir para vigilância epidemiológica e auxiliar em perícias legais.`},{id:`necr-008`,banca:`CRMV`,ano:2021,prova:`CRMV — Exame de Qualificação 2021`,tipo:`crmv`,topico:`conceitos_necropsia`,subtopico:`Laudo necroscópico`,dificuldade:`medio`,enunciado:`O laudo de necropsia (laudo necroscópico) deve conter obrigatoriamente:`,alternativas:[`Identificação do animal, dados do proprietário, histórico, descrição dos achados de necropsia (externos e internos), diagnóstico anatomopatológico e conclusão.`,`Apenas a conclusão com a causa da morte.`,`Exclusivamente fotografias dos órgãos lesados.`,`Resultados de exames laboratoriais complementares.`,`Apenas a identificação do animal e o diagnóstico final.`],resposta_correta:`A`,explicacao:`O laudo necroscópico é documento técnico-científico e legal que deve conter identificação completa do animal e proprietário, histórico clínico, descrição detalhada e sistemática dos achados externos e internos, diagnóstico anatomopatológico e conclusão. Exames complementares são registrados quando disponíveis.`},{id:`necr-009`,banca:`AVAMEC`,ano:2023,prova:`AVAMEC — Concurso 2023`,tipo:`concurso`,topico:`conceitos_necropsia`,subtopico:`Necropsia em animais de grande porte`,dificuldade:`dificil`,enunciado:`Na realização de necropsia de bovino adulto em campo, quando não é possível transportar o cadáver para local apropriado, a conduta recomendada é:`,alternativas:[`Realizar a necropsia no local do óbito, tomando cuidado com a posição do vento, distanciando de fontes de água, e proceder à desinfecção do local e disposição adequada dos restos após o procedimento.`,`Enterrar o animal imediatamente sem realizar necropsia.`,`Esperar que o cadáver seja removido por veículos especializados antes de qualquer procedimento.`,`Realizar apenas coleta de sangue post mortem e encaminhar ao laboratório.`,`Cobrir o cadáver com cal virgem e aguardar 72 horas.`],resposta_correta:`A`,explicacao:`Em campo, a necropsia deve ser realizada no local do óbito quando o transporte não é viável. Cuidados essenciais incluem posicionar-se a favor do vento, distanciar de fontes de água e habitações, proteger o cadáver de predadores e, após o procedimento, realizar desinfecção do local e disposição adequada dos restos (incineração ou enterramento com cal).`},{id:`necr-010`,banca:`USP`,ano:2022,prova:`USP — Concurso Professor 2022`,tipo:`concurso`,topico:`conceitos_necropsia`,subtopico:`Limitações da necropsia`,dificuldade:`medio`,enunciado:`Sobre as limitações da necropsia veterinária, é correto afirmar:`,alternativas:[`Alterações autolíticas avançadas, decomposição e congelamento prévio do cadáver podem comprometer a interpretação das lesões e dificultar o diagnóstico.`,`A necropsia não apresenta limitações significativas, sendo sempre possível determinar a causa mortis.`,`A única limitação relevante é a falta de equipamentos adequados.`,`Lesões histológicas sempre são preservadas mesmo em cadáveres em avançado estado de decomposição.`,`O congelamento do cadáver melhora a qualidade do exame necroscópico.`],resposta_correta:`A`,explicacao:`As principais limitações da necropsia incluem: autólise avançada, putrefação, congelamento prévio (causa artefatos de cristais de gelo), mumificação, adipocira, destruição do cadáver por predadores e tempo prolongado entre a morte e o procedimento. Esses fatores podem comprometer a interpretação macroscópica e histológica.`},{id:`necr-011`,banca:`UFRRJ`,ano:2019,prova:`UFRRJ — Concurso 2019`,tipo:`concurso`,topico:`conceitos_necropsia`,subtopico:`Necropsia e vigilância epidemiológica`,dificuldade:`facil`,enunciado:`A importância da necropsia para a vigilância epidemiológica está relacionada:`,alternativas:[`À identificação de agentes etiológicos, determinação de prevalência de doenças, detecção de surtos e fornecimento de dados para políticas de saúde animal e pública.`,`Exclusivamente à emissão de atestados de óbito para fins comerciais.`,`Apenas à verificação da idade do animal abatido.`,`À determinação do peso da carcaça para fins de comercialização.`,`Ao controle de qualidade de rações e suplementos alimentares.`],resposta_correta:`A`,explicacao:`A necropsia é ferramenta fundamental para vigilância epidemiológica, permitindo a identificação de agentes causais, determinação de prevalência de doenças, detecção precoce de surtos e doenças emergentes, e geração de dados para políticas de saúde animal e saúde pública (One Health).`},{id:`necr-012`,banca:`FCC`,ano:2024,prova:`FCC — Analista MAPA 2024`,tipo:`concurso`,topico:`conceitos_necropsia`,subtopico:`Termos necroscópicos`,dificuldade:`dificil`,enunciado:`Assinale a alternativa que apresenta corretamente a definição do termo "autopsia" e sua relação com "necropsia" na terminologia veterinária:`,alternativas:[`Autopsia e necropsia são sinônimos, sendo "necropsia" o termo preferido na área veterinária por derivar do latim (necro = morte, opsia = ver), enquanto "autopsia" vem do grego (auto = si mesmo, opsia = ver).`,`Autopsia refere-se apenas a humanos e necropsia apenas a animais, não podendo ser usados de forma intercambiável.`,`Autopsia é o exame de órgãos isolados e necropsia é o exame do corpo inteiro.`,`Necropsia é um sinônimo de biópsia post mortem.`,`Autopsia é realizada em vida e necropsia após a morte.`],resposta_correta:`A`,explicacao:`Autopsia (do grego) e necropsia (do latim) são termos sinônimos que significam "ver com os próprios olhos" o cadáver. Na medicina veterinária, o termo "necropsia" é mais utilizado, enquanto na medicina humana se prefere "autopsia". Ambos referem-se ao exame post mortem completo do cadáver.`},{id:`necr-013`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`tecnica_necropsia_bovina`,subtopico:`Posição do cadáver para necropsia bovina`,dificuldade:`facil`,enunciado:`A posição padrão para realização de necropsia em bovino é:`,alternativas:[`Decúbito lateral esquerdo, com o animal posicionado sobre o lado esquerdo, facilitando o exame dos órgãos torácicos e abdominais.`,`Decúbito dorsal, com o animal posicionado sobre o dorso.`,`Decúbito lateral direito, com o animal sobre o lado direito.`,`Posição ortostática (em pé), com auxílio de cordas.`,`Decúbito ventral, com o animal sobre o abdômen.`],resposta_correta:`A`,explicacao:`A posição padrão para necropsia bovina é o decúbito lateral esquerdo. Nessa posição, o rúmen fica para baixo, evitando deslocamento de conteúdo ruminal para os demais órgãos. Além disso, o coração e os pulmões são mais acessíveis para exame. O animal é posicionado com os membros estendidos.`},{id:`necr-014`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário MAPA 2022`,tipo:`concurso`,topico:`tecnica_necropsia_bovina`,subtopico:`Exame externo em bovino`,dificuldade:`medio`,enunciado:`Julgue o item sobre o exame externo na necropsia de bovinos:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`O exame externo na necropsia bovina deve incluir avaliação do estado nutricional, pelagem, mucosas visíveis (ocular, nasal, oral, anal, genital), presença de parasitas externos, feridas, edemas, enfisema subcutâneo, linfonodos superficiais (pré-escapulares, pré-crurais, inguinais), cavidades naturais (oral, nasal, anal, vaginal) e odor do cadáver.`,explicacao:`O exame externo é a primeira etapa da necropsia e fornece informações fundamentais. Em bovinos, deve-se avaliar sistematicamente: estado nutricional, integridade da pele e pelagem, coloração das mucosas (icterícia, palidez, cianose), secreções, excreções, presença de parasitas externos, edemas subcutâneos, enfisema, e palpação dos linfonodos superficiais.`},{id:`necr-015`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso 2021`,tipo:`concurso`,topico:`tecnica_necropsia_bovina`,subtopico:`Abertura da cavidade abdominal em bovino`,dificuldade:`medio`,enunciado:`Na abertura da cavidade abdominal de bovino durante a necropsia, a técnica correta consiste em:`,alternativas:[`Realizar incisão na linha alba, desde o apêndice xifoide até o púbis, com cuidado para não perfurar o rúmen, e em seguida realizar incisões laterais na região inguinal para ampliação do acesso.`,`Abrir apenas o flanco direito para acesso ao abomaso.`,`Realizar incisão transversal na região lombar.`,`Perfurar o rúmen com bisturi para retirada do conteúdo ruminal.`,`Abrir a cavidade pelo dorso, removendo as vértebras lombares.`],resposta_correta:`A`,explicacao:`A abertura da cavidade abdominal em bovino segue a técnica de incisão na linha alba (linha mediana ventral), desde o apêndice xifoide até a região púbica. Devem-se realizar incisões laterais na região inguinal para ampliação. É fundamental ter cuidado para não perfurar o rúmen, que ocupa grande parte do abdômen esquerdo, evitando contaminação.`},{id:`necr-016`,banca:`UFMG`,ano:2023,prova:`UFMG — Concurso 2023`,tipo:`concurso`,topico:`tecnica_necropsia_bovina`,subtopico:`Exame interno dos órgãos torácicos em bovino`,dificuldade:`dificil`,enunciado:`Durante o exame interno dos órgãos torácicos de bovino, a ordem recomendada de avaliação é:`,alternativas:[`Verificar o volume e características do líquido pleural/pericárdico, examinar o pericárdio e coração, e por fim avaliar os pulmões e mediastino.`,`Remover os pulmões primeiro e depois examinar o coração in situ.`,`Examinar apenas o coração, pois os pulmões raramente apresentam lesões significativas em bovinos.`,`Avaliar o esôfago torácico antes de qualquer órgão da cavidade.`,`Abrir diretamente o coração sem avaliar o pericárdio.`],resposta_correta:`A`,explicacao:`No exame torácico de bovino, a sequência recomendada é: 1) verificar volume e aspecto do líquido pleural e pericárdico; 2) examinar o pericárdio (espessura, aderências); 3) examinar o coração (endocárdio, miocárdio, válvulas, grandes vasos); 4) examinar os pulmões (consistência, coloração, presença de lesões); 5) avaliar mediastino e linfonodos.`},{id:`necr-017`,banca:`ENAV`,ano:2024,prova:`ENAV — Residência 2024`,tipo:`residencia`,topico:`tecnica_necropsia_bovina`,subtopico:`Exame do sistema digestório em bovino`,dificuldade:`medio`,enunciado:`Na necropsia de bovino, ao examinar o trato gastrointestinal, o médico veterinário deve:`,alternativas:[`Avaliar separadamente rúmen, retículo, omaso e abomaso, verificando conteúdo, mucosa e espessura da parede; no intestino, examinar delgado e grosso, com atenção ao íleo, ceco e cólon espiralado.`,`Examinar apenas o abomaso, por ser o único compartimento funcional.`,`Abrir todos os compartimentos ruminais simultaneamente.`,`Descartar o rúmen sem exame, pois seu conteúdo interfere nos demais órgãos.`,`Examinar apenas o intestino grosso para busca de parasitas.`],resposta_correta:`A`,explicacao:`O trato gastrointestinal bovino requer exame individualizado de cada compartimento: rúmen (volume e aspecto do conteúdo, papilas, integridade da mucosa), retículo (corpos estranhos, reticulite), omaso (lâminas omasais), abomaso (úlceras, parasitas, espessura da mucosa) e intestinos. O cólon espiralado é particularmente importante em bovinos.`},{id:`necr-018`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário 2022`,tipo:`concurso`,topico:`tecnica_necropsia_bovina`,subtopico:`Coleta de material na necropsia bovina`,dificuldade:`facil`,enunciado:`Para exame histopatológico em necropsia de bovino, o material deve ser:`,alternativas:[`Fragmentos de órgãos com lesão e sem lesão, com espessura máxima de 1 cm, fixados em formol a 10% em volume pelo menos 10 vezes superior ao volume do fragmento.`,`Órgãos inteiros sem fixação, enviados em sacos plásticos.`,`Fragmentos de qualquer espessura, fixados em álcool 70%.`,`Apenas sangue coletado post mortem, sem fixação.`,`Fragmentos de 10 cm de espessura, fixados em formol a 1%.`],resposta_correta:`A`,explicacao:`Para histopatologia, os fragmentos devem ter no máximo 1 cm de espessura para permitir a penetração adequada do fixador. O formol a 10% (formaldeído a 4%) deve estar em volume pelo menos 10 vezes superior ao do fragmento. Devem ser coletados fragmentos tanto da área lesada quanto da transição lesão/tecido normal.`},{id:`necr-019`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso 2020`,tipo:`concurso`,topico:`tecnica_necropsia_bovina`,subtopico:`Cuidados especiais em necropsia de bovino`,dificuldade:`dificil`,enunciado:`Em necropsia de bovino com suspeita de carbúnculo sintomático (Clostridium chauvoei), o procedimento adequado é:`,alternativas:[`Não realizar necropsia em caso de suspeita fortemente fundamentada, pois a abertura do cadáver pode liberar esporos e contaminar o ambiente. Coletar apenas fragmentos de músculo lesado por punção com agulha grossa e encaminhar ao laboratório.`,`Realizar necropsia completa normalmente, sem precauções adicionais.`,`Apenas colher sangue do cadáver e descartar o restante.`,`Realizar a necropsia em local com ventilação artificial.`,`Esperar 48 horas para que os esporos percam viabilidade antes de necropsiar.`],resposta_correta:`A`,explicacao:`Em suspeita de carbúnculo sintomático e outros clostridioses, a necropsia completa é contraindicada por risco de contaminação ambiental com esporos. O diagnóstico pode ser obtido por coleta de fragmento muscular lesado com agulha grossa (sem abertura do cadáver), impressão de fragmentos e exame bacteriológico. O cadáver deve ser incinerado.`},{id:`necr-020`,banca:`MAPA`,ano:2023,prova:`MAPA — Serviço de Inspeção 2023`,tipo:`concurso`,topico:`tecnica_necropsia_bovina`,subtopico:`Exame do fígado e vias biliares em bovino`,dificuldade:`medio`,enunciado:`No exame hepático durante a necropsia de bovino, deve-se avaliar:`,alternativas:[`Tamanho, consistência, coloração, presença de parasitas (Fasciola hepática), abscessos, necrose, e examinar a vesícula biliar e vias biliares.`,`Apenas o tamanho e o peso do fígado.`,`Somente a vesícula biliar, desprezando o parênquima hepático.`,`Exclusivamente a coloração do fígado, sem incisão do órgão.`,`Apenas em bovinos com mais de 5 anos de idade.`],resposta_correta:`A`,explicacao:`O exame hepático em bovino deve ser completo e sistemático: avaliar tamanho, consistência, coloração (icterícia, palidez, congestão), incisões para verificar o parênquima (necrose, abscessos, parasitas como Fasciola hepática e Dicrocoelium dendriticum), e examinar a vesícula biliar (conteúdo, mucosa, espessura da parede) e vias biliares intra-hepáticas.`},{id:`necr-021`,banca:`USP`,ano:2021,prova:`USP — Concurso 2021`,tipo:`concurso`,topico:`tecnica_necropsia_bovina`,subtopico:`Exame do sistema nervoso em bovino`,dificuldade:`dificil`,enunciado:`Para o exame do sistema nervoso central em bovino durante a necropsia, a técnica de abertura da caixa craniana consiste em:`,alternativas:[`Remover a pele e musculatura do crânio, realizar cortes com serrote ósseo nos ossos frontais, parietais e occipital, e remover a calota craniana com auxílio de formão e martelo, expondo o encéfalo.`,`Fraturar o crânio com golpes de martelo sem uso de serrote.`,`Acessar o encéfalo pela base do crânio, pelo forame magno.`,`Realizar cortes com bisturi apenas nos ossos mais finos.`,`Não é necessário abrir o crânio em bovinos; o exame do SNC é feito por punção lombar.`],resposta_correta:`A`,explicacao:`A abertura da caixa craniana em bovino requer serrote ósseo para cortes nos ossos frontais, parietais e occipital, seguidos de uso de formão e martelo para destacar a calota craniana. Deve-se ter cuidado para não lesar o encéfalo. O encéfalo é então examinado in situ e, se necessário, removido para exame mais detalhado.`},{id:`necr-022`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Concurso 2022`,tipo:`concurso`,topico:`tecnica_necropsia_bovina`,subtopico:`Exame do sistema urinário em bovino`,dificuldade:`facil`,enunciado:`No exame do sistema urinário de bovino durante a necropsia, deve-se:`,alternativas:[`Avaliar rins (tamanho, consistência, coloração, cápsula, córtex, medula), ureteres, bexiga (cheia de urina ou vazia, mucosa) e uretra.`,`Examinar apenas os rins, desprezando ureteres e bexiga.`,`Remover os rins sem abrir, apenas para pesagem.`,`Examinar apenas a bexiga, que é o órgão mais importante do sistema urinário.`,`Avaliar o sistema urinário apenas em fêmeas, pois em machos não há relevância.`],resposta_correta:`A`,explicacao:`O exame do sistema urinário deve ser completo: rins (tamanho, cor, consistência, facilidade de decapsulação, relação córtex-medula, presença de cálculos ou lesões), ureteres (calibre, permeabilidade), bexiga (volume de urina, aspecto da mucosa, presença de cálculos) e uretra. Em bovinos, a nefrite intersticial e pielonefrite são achados frequentes.`},{id:`necr-023`,banca:`CRMV`,ano:2023,prova:`CRMV — Exame 2023`,tipo:`crmv`,topico:`tecnica_necropsia_bovina`,subtopico:`Exame do sistema reprodutor em bovino`,dificuldade:`medio`,enunciado:`Na necropsia de vaca gestante morta por suspeita de hérnia diafragmática, antes de abrir a cavidade torácica o veterinário deve:`,alternativas:[`Abrir primeiro a cavidade abdominal e realizar cesariana para retirada do feto, evitando que o feto seja danificado durante o exame torácico e permitindo avaliação separada dos conceptos.`,`Abrir simultaneamente as cavidades torácica e abdominal.`,`Não realizar a cesariana, pois o feto não tem valor diagnóstico.`,`Encaminhar o cadáver inteiro para exame de imagem.`,`Remover apenas o útero sem abrir a cavidade abdominal.`],resposta_correta:`A`,explicacao:`Em fêmeas gestantes, a cesariana post mortem deve ser realizada antes de procedimentos que possam danificar o concepto. O feto e anexos fetais têm valor diagnóstico (infecções congênitas, malformações). Após a cesariana, procede-se à necropsia normal da matriz e da cadela/vaca.`},{id:`necr-024`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`tecnica_necropsia_equina`,subtopico:`Posição e abordagem na necropsia equina`,dificuldade:`facil`,enunciado:`A posição padrão para necropsia de equino e a principal diferença em relação à necropsia bovina são:`,alternativas:[`Decúbito lateral esquerdo, semelhante à bovina, porém com atenção especial ao estômago distendido que pode romper espontaneamente, e ao ceco volumoso no flanco direito.`,`Decúbito dorsal, diferente da posição lateral usada em bovinos.`,`Decúbito lateral direito, posição exclusiva para equinos.`,`Posição ortostativa com suspensão do cadáver por guindaste.`,`Decúbito ventral, para facilitar o acesso ao sistema nervoso.`],resposta_correta:`A`,explicacao:`Na necropsia equina, a posição padrão é decúbito lateral esquerdo (semelhante à bovina). A principal diferença técnica é a atenção ao estômago equino (não ruminante, com capacidade limitada), que pode estar distendido e romper durante a manipulação. O ceco volumoso ocupa o flanco direito e requer cuidado na abertura.`},{id:`necr-025`,banca:`CESPE`,ano:2021,prova:`CESPE — Veterinário 2021`,tipo:`concurso`,topico:`tecnica_necropsia_equina`,subtopico:`Exame do sistema digestório em equino`,dificuldade:`medio`,enunciado:`No exame do trato gastrointestinal de equino durante a necropsia, é CORRETO afirmar:`,alternativas:[`O intestino grosso do equino deve ser examinado com cuidado especial devido ao grande volume do cólon ventral direito e esquerdo e do ceco, que podem conter grande quantidade de conteúdo e apresentar distensão, volvulo ou deslocamento.`,`O intestino grosso equino é pequeno e de pouca relevância diagnóstica.`,`O estômago equino deve ser aberto in situ antes da remoção dos órgãos.`,`O ceco equino não necessita de exame detalhado.`,`O intestino delgado é o único segmento gastrointestinal relevante em equinos.`],resposta_correta:`A`,explicacao:`O intestino grosso do equino é extremamente desenvolvido e volumoso, sendo responsável pela fermentação microbiana. O ceco, cólon ventral e cólon dorsal devem ser examinados com atenção para distensão gasosa, volvulos, deslocamentos, impactação e lesões de mucosa. A cólica é uma causa importante de morte em equinos.`},{id:`necr-026`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Concurso 2022`,tipo:`concurso`,topico:`tecnica_necropsia_equina`,subtopico:`Exame do sistema musculoesquelético em equino`,dificuldade:`medio`,enunciado:`Na necropsia de equino com suspeita de mioglobinúria (rabdomiólise), a coleta adequada de material inclui:`,alternativas:[`Fragmentos dos músculos afetados (geralmente glúteo, semimembranoso e semitendinoso), fixados em formol a 10% para histopatologia, e amostra congelada para dosagem de mioglobina e enzimas musculares.`,`Apenas amostra de sangue post mortem.`,`Fragmentos de fígado apenas.`,`Apenas amostra de urina coletada da bexiga post mortem.`,`Não é necessário coletar material, pois o diagnóstico é baseado apenas na história clínica.`],resposta_correta:`A`,explicacao:`Na rabdomiólise equina (mioglobinúria), os músculos mais afetados (glúteos, semimembranoso, semitendinoso) devem ser coletados para histopatologia (necrose muscular, edema, hemorragia) e amostras congeladas para dosagens bioquímicas. A mioglobina na urina (urina escura) é característica, mas o diagnóstico definitivo é histopatológico.`},{id:`necr-027`,banca:`UFMG`,ano:2020,prova:`UFMG — Concurso 2020`,tipo:`concurso`,topico:`tecnica_necropsia_equina`,subtopico:`Exame do sistema respiratório em equino`,dificuldade:`dificil`,enunciado:`No exame do sistema respiratório de equino durante a necropsia, além de pulmões e traqueia, deve-se avaliar obrigatoriamente:`,alternativas:[`Seios da face (frontal, maxilar), cavidade nasal, cornetos, laringe e faringe, pois equinos são frequentemente acometidos por doenças que afetam essas estruturas (gurma, sinusite, hemorragia pulmonar por exercício).`,`Apenas os pulmões, que são os únicos órgãos relevantes do sistema respiratório equino.`,`Somente a traqueia e brônquios, sem necessidade de examinar cavidade nasal.`,`Exclusivamente o diafragma, para verificação de hérnias.`,`Apenas os linfonodos bronquiais.`],resposta_correta:`A`,explicacao:`O sistema respiratório equino requer exame completo das vias aéreas superiores e inferiores: cavidade nasal (mucosa, secreções), cornetos, seios da face (frontal, maxilar), faringe, laringe (fossa cecal, cartilagens), traqueia e pulmões. Equinos apresentam doenças respiratórias específicas como gurma (Streptococcus equi), hemorragia pulmonar por exercício e adenite equina.`},{id:`necr-028`,banca:`ENAV`,ano:2024,prova:`ENAV — Residência 2024`,tipo:`residencia`,topico:`tecnica_necropsia_equina`,subtopico:`Exame do sistema cardiovascular em equino`,dificuldade:`medio`,enunciado:`Na necropsia de equino, o exame do coração deve incluir:`,alternativas:[`Avaliação do pericárdio (volume líquido, aderências), abertura das câmaras cardíacas seguindo o fluxo sanguíneo, exame das válvulas (endocardite, vegetações), miocárdio (necrose, fibrose, palidez) e grandes vasos.`,`Apenas verificação do peso do coração.`,`Exame apenas do miocárdio, sem abertura das câmaras.`,`Apenas palpação externa do coração sem incisão.`,`Exame cardíaco apenas em equinos com mais de 10 anos.`],resposta_correta:`A`,explicacao:`O exame cardíaco em equino deve ser completo: verificar líquido pericárdico (hidropericárdio, hemopericárdio), aderências, abrir as câmaras seguindo o fluxo sanguíneo (átrio direito → ventrículo direito → artéria pulmonar; átrio esquerdo → ventrículo esquerdo → aorta), examinar válvulas (endocardite valvular é comum em equinos), miocárdio e grandes vasos.`},{id:`necr-029`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário 2023`,tipo:`concurso`,topico:`tecnica_necropsia_equina`,subtopico:`Cuidados específicos na necropsia equina`,dificuldade:`facil`,enunciado:`Ao realizar necropsia de equino, um cuidado fundamental que difere da necropsia de bovinos é:`,alternativas:[`Cuidado com o estômago distendido, que pode romper durante a manipulação, liberando conteúdo gástrico ácido e causando artefatos.`,`A necessidade de usar serrote ósseo para todos os ossos.`,`A impossibilidade de examinar o sistema nervoso central.`,`A necessidade de posicionar o animal em decúbito dorsal.`,`O uso obrigatório de bisturi elétrico.`],resposta_correta:`A`,explicacao:`O estômago equino, por ser um estômago simples (não ruminante), pode apresentar distensão gasosa post mortem. Se romper durante a manipulação, o conteúdo gástrico ácido causa autólise e artefatos nos tecidos adjacentes. Deve-se realizar pequena punção descompressiva antes da manipulação intensa.`},{id:`necr-030`,banca:`UNESP`,ano:2021,prova:`UNESP — Concurso 2021`,tipo:`concurso`,topico:`tecnica_necropsia_equina`,subtopico:`Exame do sistema nervoso em equino`,dificuldade:`dificil`,enunciado:`Na necropsia de equino com suspeita de encefalomielite equina (encefalite viral), o exame do sistema nervoso central deve incluir:`,alternativas:[`Abertura da caixa craniana com serrote ósseo, exame macroscópico do encéfalo (meninges, cortical, substância branca, cerebelo, tronco encefálico), e coleta de fragmentos de diferentes regiões para histopatologia e diagnóstico viral.`,`Apenas coleta de líquido cefalorraquidiano por punção lombar.`,`Exame apenas do tronco encefálico.`,`Não é necessário exame do SNC em casos de encefalomielite.`,`Exclusivamente exame da medula espinhal cervical.`],resposta_correta:`A`,explicacao:`Em suspeita de encefalomielite equina (encefalite viral, herpesvírus, raiva), o exame completo do SNC é indispensável. Deve-se abrir a caixa craniana, examinar meninges (congestão, edema, hemorragia), cortical, substância branca, cerebelo e tronco encefálico, e coletar fragmentos de múltiplas regiões para histopatologia, imunohistoquímica e PCR.`},{id:`necr-031`,banca:`MAPA`,ano:2022,prova:`MAPA — Serviço Veterinário 2022`,tipo:`concurso`,topico:`tecnica_necropsia_equina`,subtopico:`Exame dos cascos e membros em equino`,dificuldade:`medio`,enunciado:`O exame dos cascos e membros na necropsia de equino é importante porque:`,alternativas:[`Afecções podais (laminites, pododermatites, fraturas) são causas frequentes de debilidade e morte em equinos, e o exame detalhado pode revelar lesões infecciosas, degenerativas ou traumáticas.`,`Os cascos não têm relevância diagnóstica na necropsia.`,`O exame dos cascos é exclusivo para cavalos de esporte.`,`Apenas fraturas expostas devem ser avaliadas.`,`O exame dos membros é dispensável em equinos adultos.`],resposta_correta:`A`,explicacao:`O exame dos cascos e membros é essencial em equinos. A laminites (pododermatite asséptica difusa), fraturas, artrites sépticas e pododermatites são causas importantes de morbidade e mortalidade. O casco deve ser seccionado (corte de Caslick ou secção sagital) para avaliação da lâmina, osso do dedo e estruturas internas.`},{id:`necr-032`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Concurso 2023`,tipo:`concurso`,topico:`tecnica_necropsia_equina`,subtopico:`Exame do sistema linfático em equino`,dificuldade:`medio`,enunciado:`O exame dos linfonodos na necropsia equina deve incluir obrigatoriamente:`,alternativas:[`Linfonodos submandibulares, retrofaríngeos, mediastínicos, mesentéricos, pré-escapulares e pré-crurais, avaliando tamanho, consistência, coloração e presença de abscessos ou neoplasias.`,`Apenas os linfonodos superficiais visíveis durante o exame externo.`,`Exclusivamente os linfonodos mesentéricos.`,`Não é necessário examinar linfonodos em equinos.`,`Apenas os linfonodos inguinais.`],resposta_correta:`A`,explicacao:`O exame dos linfonodos em equinos é fundamental, especialmente para diagnóstico de adenite equina (Streptococcus equi subsp. equi), linfoma, metástases neoplásicas e infecções sistêmicas. Os principais grupos a serem avaliados são submandibulares, retrofaríngeos, mediastínicos, mesentéricos, bronquiais, pré-escapulares e pré-crurais.`},{id:`necr-033`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`tecnica_necropsia_canina_felina`,subtopico:`Posição e abordagem na necropsia de cães e gatos`,dificuldade:`facil`,enunciado:`A posição padrão para necropsia de cães e gatos é:`,alternativas:[`Decúbito lateral esquerdo ou decúbito dorsal (quando o animal é pequeno), com os membros fixados para facilitar o exame.`,`Decúbito ventral obrigatório para todos os pequenos animais.`,`Suspensão vertical com fixação em suporte.`,`Não há posição padrão; o veterinário escolhe livremente.`,`Apenas decúbito lateral direito.`],resposta_correta:`A`,animais_pequenos:!0,explicacao:`Para cães e gatos, o decúbito lateral esquerdo é mais comum em animais de porte maior, enquanto o decúbito dorsal é frequentemente utilizado em animais pequenos e gatos, facilitando a abertura bilateral das cavidades. Os membros são fixados com barbantes ou grampos para manter a posição.`},{id:`necr-034`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`tecnica_necropsia_canina_felina`,subtopico:`Exame externo em cães e gatos`,dificuldade:`medio`,enunciado:`Julgue o item sobre o exame externo na necropsia de cães e gatos:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`O exame externo em cães e gatos deve incluir avaliação das mucosas (ocular, oral, genital, anal), estado nutricional, pelagem, presença de ectoparasitas (pulgas, carrapatos, piolhos), feridas, nódulos, edemas, e palpação dos linfonodos superficiais (submandibulares, poplíteos, axilares, inguinais). A cavidade oral deve ser examinada para úlceras, lesões de gengivas e dentes.`,explicacao:`O exame externo em pequenos animais segue os mesmos princípios dos grandes animais, com atenção especial a ectoparasitas (indicadores de imunossupressão ou negligência), lesões de mucosa oral (uremia, virose), e condições de pelagem e estado nutricional.`},{id:`necr-035`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso 2021`,tipo:`concurso`,topico:`tecnica_necropsia_canina_felina`,subtopico:`Abertura de cavidades em cães e gatos`,dificuldade:`medio`,enunciado:`Na abertura das cavidades torácica e abdominal em cães e gatos, a técnica recomendada é:`,alternativas:[`Incisão mediana ventral do apêndice xifoide até a região púbica, com incisões laterais, seguida de abertura torácica por ressecção das costelas com tesoura ou serrote, expondo os órgãos torácicos.`,`Abertura apenas pelo flanco direito.`,`Ressecção completa do esterno antes de abrir o abdômen.`,`Abertura torácica exclusivamente pelo dorso.`,`Incisão transversal na região umbilical.`],resposta_correta:`A`,explicacao:`A técnica padrão para pequenos animais envolve: 1) incisão mediana ventral (linha alba) do xifoide ao púbis; 2) incisões laterais na região inguinal; 3) abertura torácica por ressecção das costelas com tesoura de Liston ou serrote, expondo a cavidade torácica e seus órgãos.`},{id:`necr-036`,banca:`UFMG`,ano:2023,prova:`UFMG — Concurso 2023`,tipo:`concurso`,topico:`tecnica_necropsia_canina_felina`,subtopico:`Exame do sistema digestório em cães`,dificuldade:`medio`,enunciado:`No exame do trato gastrointestinal de cães e gatos durante a necropsia, deve-se:`,alternativas:[`Avaliar esôfago, estômago (presença de corpos estranhos, úlceras, parasitas), intestino delgado e grosso (intussuscepção, volvulo, parasitas, lesões de mucosa), pâncreas, fígado e vesícula biliar.`,`Examinar apenas o estômago e intestino delgado.`,`Apenas verificar a presença de corpos estranhos no estômago.`,`Examinar exclusivamente o fígado e pâncreas.`,`Avaliar apenas o intestino grosso em gatos.`],resposta_correta:`A`,explicacao:`O exame gastrointestinal em pequenos animais deve ser completo. Corpos estranhos são frequentes em cães e gatos. Deve-se avaliar esôfago (megae esôfago, corpo estranho), estômago (úlceras, parasitas como Physaloptera), intestinos (intussuscepção, enterite, parasitas), pâncreas (pancreatite), fígado e vesícula biliar.`},{id:`necr-037`,banca:`ENAV`,ano:2024,prova:`ENAV — Residência 2024`,tipo:`residencia`,topico:`tecnica_necropsia_canina_felina`,subtopico:`Exame do sistema respiratório em cães e gatos`,dificuldade:`facil`,enunciado:`No exame do sistema respiratório de cães e gatos na necropsia, deve-se avaliar:`,alternativas:[`Cavidade nasal, seios da face, faringe, laringe, traqueia, brônquios, pulmões (consistência, coloração, presença de edema, pneumonia, neoplasias) e linfonodos bronquiais.`,`Apenas os pulmões.`,`Exclusivamente a traqueia e laringe.`,`Somente a cavidade nasal em gatos.`,`Apenas os pulmões em cães braquicefálicos.`],resposta_correta:`A`,explicacao:`O exame respiratório em pequenos animais deve ser completo: cavidade nasal (rinite, corpos estranhos, neoplasias), seios da face, faringe, laringe (paralisia laríngea em cães idosos), traqueia (colapso traqueal), brônquios, pulmões (edema, pneumonia, neoplasias) e linfonodos bronquiais e mediastínicos.`},{id:`necr-038`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário 2022`,tipo:`concurso`,topico:`tecnica_necropsia_canina_felina`,subtopico:`Exame do sistema urinário em cães e gatos`,dificuldade:`medio`,enunciado:`O exame do sistema urinário em cães e gatos durante a necropsia deve incluir:`,alternativas:[`Rins (tamanho, cápsula, relação córtex-medula, presença de cálculos ou cistos), ureteres, bexiga (volume urinário, espessura da parede, cálculos, neoplasias) e uretra.`,`Apenas os rins e a bexiga.`,`Exclusivamente a bexiga, por ser mais acessível.`,`Apenas os rins, sem necessidade de abrir o órgão.`,`Somente a uretra em machos.`],resposta_correta:`A`,explicacao:`O sistema urinário em pequenos animais requer exame completo: rins (doença renal crônica é muito comum em gatos idosos, rins policísticos em gatos Persas), ureteres, bexiga (cistite, urolitíase, neoplasias como carcinoma de células transicionais) e uretra (obstrução uretral em gatos machos).`},{id:`necr-039`,banca:`CRMV`,ano:2021,prova:`CRMV — Exame 2021`,tipo:`crmv`,topico:`tecnica_necropsia_canina_felina`,subtopico:`Exame do sistema reprodutor em cães e gatos`,dificuldade:`medio`,enunciado:`Na necropsia de cadela com suspeita de piometra que veio a óbito, o exame do sistema reprodutor deve incluir:`,alternativas:[`Avaliação dos ovários (cistos, neoplasias), útero (volume de conteúdo purulento, espessura da parede, necrose, perfuração), cérvix e vagina, com coleta de material para bacteriologia e histopatologia.`,`Apenas visualização externa do útero.`,`Exame apenas dos ovários.`,`Não é necessário examinar o sistema reprodutor em fêmeas.`,`Exclusivamente avaliação da vagina.`],resposta_correta:`A`,explicacao:`A piometra é uma causa comum de morte em cadelas não castradas. O útero encontra-se distendido com conteúdo purulento, a parede pode estar necrótica e há risco de perfuração e peritonite. O exame deve incluir ovários (cistos foliculares, neoplasias), útero, cérvix e vagina, com coleta para bacteriologia (E. coli é frequente) e histopatologia.`},{id:`necr-040`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso 2020`,tipo:`concurso`,topico:`tecnica_necropsia_canina_felina`,subtopico:`Exame do sistema cardiovascular em cães e gatos`,dificuldade:`dificil`,enunciado:`Na necropsia de cães de raças grandes com suspeita de hemangiossarcoma esplênico, o exame deve incluir:`,alternativas:[`Avaliação detalhada do baço (tamanho, presença de massas, hemorragia, ruptura), coração (massas no átrio direito, hemopericárdio), fígado (metástases) e pulmões (metástases), com coleta de fragmentos de todas as lesões.`,`Apenas o exame do baço.`,`Exclusivamente o coração, sem avaliar outros órgãos.`,`Apenas exame externo do cadáver.`,`Não é necessário exame do baço na necropsia de rotina.`],resposta_correta:`A`,explicacao:`O hemangiossarcoma é neoplasia maligna frequente em cães de raças grandes (Pastor Alemão, Golden Retriever, Labrador), com localização primária mais comum no baço e coração (átrio direito). A ruptura tumoral causa hemorragia interna e morte súbita. O exame deve ser sistêmico para avaliar metástases hepáticas e pulmonares.`},{id:`necr-041`,banca:`AVAMEC`,ano:2023,prova:`AVAMEC — Concurso 2023`,tipo:`concurso`,topico:`tecnica_necropsia_canina_felina`,subtopico:`Necropsia em filhotes de cães e gatos`,dificuldade:`medio`,enunciado:`Na necropsia de filhotes de cães e gatos que morreram neonatalmente, é importante:`,alternativas:[`Avaliar a presença de malformações congênitas, verificar o cordão umbilical (onfalite, tétano), examinar o conteúdo gástrico (presença de leite indicando que mamou), e coletar material para diagnóstico de infecções congênitas.`,`Não realizar necropsia em neonatos, pois as lesões não são interpretáveis.`,`Examinar apenas o cordão umbilical.`,`Apenas verificar o peso do filhote.`,`Esperar o filhote completar 30 dias para realizar o exame.`],resposta_correta:`A`,explicacao:`A necropsia neonatal é importante para identificar malformações congênitas (palato fendido, hérnias, cardiopatias), infecções congênitas (herpesvírus canino, panleucopenia felina), onfalite, onfaloflebite, e verificar se o neonato mamou (presença de leite coagulado no estômago), o que indica sobrevida pós-parto.`},{id:`necr-042`,banca:`USP`,ano:2022,prova:`USP — Concurso 2022`,tipo:`concurso`,topico:`tecnica_necropsia_canina_felina`,subtopico:`Exame do sistema nervoso em cães e gatos`,dificuldade:`dificil`,enunciado:`Para o exame do sistema nervoso central em cães e gatos, a técnica de abertura da caixa craniana em animais pequenos permite:`,alternativas:[`Uso de tesoura de Liston para crânios mais delicados (gatos e cães de pequeno porte) ou serrote ósseo para cães de grande porte, com remoção da calota craniana e exame do encéfalo in situ antes da remoção.`,`Apenas fratura manual do crânio.`,`Não é possível examinar o SNC em pequenos animais.`,`Apenas punção lombar para coleta de LCR.`,`Exame exclusivamente por imagem (TC/RM) antes da necropsia.`],resposta_correta:`A`,explicacao:`Em gatos e cães de pequeno porte, a tesoura de Liston pode ser utilizada para cortar os ossos cranianos mais finos. Em cães de grande porte, utiliza-se serrote ósseo. O encéfalo deve ser examinado in situ (meninges, superfície cortical, vasos) antes da remoção para exame mais detalhado e coleta de fragmentos.`},{id:`necr-043`,banca:`MAPA`,ano:2024,prova:`MAPA — Analista 2024`,tipo:`concurso`,topico:`tecnica_necropsia_canina_felina`,subtopico:`Coleta de material em necropsia de cães e gatos`,dificuldade:`facil`,enunciado:`Para diagnóstico de cinomose canina por necropsia, o material de escolha para exame laboratorial é:`,alternativas:[`Fragmentos de encéfalo, medula espinhal, bexiga (epitélio de transição), pulmão e linfonodos, fixados em formol a 10% para histopatologia e imuno-histoquímica.`,`Apenas amostra de sangue post mortem.`,`Fragmentos de pele apenas.`,`Apenas amostra de fezes.`,`Exclusivamente fragmentos de fígado.`],resposta_correta:`A`,explicacao:`A cinomose é causada pelo vírus da cinomose canina (paramyxovírus). Para diagnóstico histopatológico, devem ser coletados: encéfalo (corpúsculos de inclusão intranucleares), medula espinhal, bexiga (epitélio de transição é o local mais sensível para detecção de corpúsculos de inclusão), pulmões e linfonodos. Imuno-histoquímica aumenta a sensibilidade.`},{id:`necr-044`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`tecnica_necropsia_suina`,subtopico:`Posição e abordagem na necropsia suína`,dificuldade:`facil`,enunciado:`A posição padrão para necropsia de suínos e a principal particularidade técnica são:`,alternativas:[`Decúbito lateral esquerdo ou direito, com atenção ao grande volume do estômago e à presença de gordura mesentérica abundante que dificulta a visualização dos órgãos.`,`Decúbito dorsal obrigatório para suínos.`,`Posição ortostativa com suspensão dos membros anteriores.`,`Decúbito ventral para facilitar o acesso ao sistema respiratório.`,`Não há posição padrão para suínos.`],resposta_correta:`A`,explicacao:`A necropsia suína segue os princípios gerais, com decúbito lateral. A particularidade é a gordura mesentérica e omento abundante em suínos adultos, que pode dificultar a visualização dos órgãos abdominais. O estômago suíno é relativamente grande e deve ser manipulado com cuidado.`},{id:`necr-045`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`tecnica_necropsia_suina`,subtopico:`Exame do sistema respiratório em suínos`,dificuldade:`medio`,enunciado:`Julgue o item sobre o exame do sistema respiratório na necropsia de suínos:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`O exame do sistema respiratório em suínos deve incluir cavidade nasal (atrofia rinite — Rhinitis atrophicans), seios da face, laringe, traqueia, pulmões (pneumonia enzoótica, PRRS, Actinobacillus pleuropneumoniae, Mycoplasma hyopneumoniae) e linfonodos mediastínicos e bronquiais. Os pulmões suínos frequentemente apresentam consolidação cranioventral típica de pneumonia bacteriana.`,explicacao:`As doenças respiratórias são um dos maiores problemas sanitários na suinocultura. A pneumonia enzoótica (Mycoplasma hyopneumoniae) apresenta consolidação cranioventral característica. A rinite atrófica (Bordetella bronchiseptica, Pasteurella multocida) causa deformação dos cornetos nasais.`},{id:`necr-046`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso 2021`,tipo:`concurso`,topico:`tecnica_necropsia_suina`,subtopico:`Exame do sistema digestório em suínos`,dificuldade:`medio`,enunciado:`No exame do trato gastrointestinal de suínos, a avaliação deve incluir:`,alternativas:[`Esôfago, estômago, intestino delgado (jejuno e íleo — enterite proliferativa por Lawsonia intracellularis), ceco, cólon (disenteria suína por Brachyspira hyodysenteriae, Salmonella), fígado e vesícula biliar.`,`Apenas o estômago e intestino delgado.`,`Exclusivamente o fígado, que é o órgão mais acometido em suínos.`,`Apenas o intestino grosso.`,`Exame gastrointestinal apenas em leitões neonatos.`],resposta_correta:`A`,explicacao:`O trato gastrointestinal suíno é acometido por diversas enfermidades: úlceras gástricas (frequentes em suínos de terminação), enterite proliferativa (Lawsonia intracellularis), disenteria suína (Brachyspira hyodysenteriae — colite hemorrágica), salmonelose, e infecções por Clostridium em leitões.`},{id:`necr-047`,banca:`UFMG`,ano:2020,prova:`UFMG — Concurso 2020`,tipo:`concurso`,topico:`tecnica_necropsia_suina`,subtopico:`Exame do sistema linfático em suínos`,dificuldade:`medio`,enunciado:`O exame dos linfonodos em suínos é particularmente importante para diagnóstico de:`,alternativas:[`Tuberculose (Mycobacterium avium subsp. avium), linfadenite caseosa, erisipela suína (linfadenite e artrite) e linfoma.`,`Apenas parasitoses gastrointestinais.`,`Exclusivamente fraturas ósseas.`,`Não há relevância diagnóstica dos linfonodos em suínos.`,`Apenas para diagnóstico de intoxicações.`],resposta_correta:`A`,explicacao:`Os linfonodos suínos apresentam arquitetura lobulada característica. São fundamentais para diagnóstico de tuberculose aviar (M. avium — muito mais comum que M. bovis em suínos), erisipela suína (Erysipelothrix rhusiopathiae), linfoma e metástases neoplásicas.`},{id:`necr-048`,banca:`ENAV`,ano:2024,prova:`ENAV — Residência 2024`,tipo:`residencia`,topico:`tecnica_necropsia_suina`,subtopico:`Exame do sistema reprodutor em suínos`,dificuldade:`dificil`,enunciado:`Na necropsia de leitões neonatos mortos em surto agudo, o exame deve incluir avaliação do sistema reprodutor da matriz para:`,alternativas:[`Verificar a presença de endometrite, metrite, retenção de placenta e infecções uterinas que podem ter causado sepia neonatal nos leitões.`,`Apenas verificar o número de leitões nascidos.`,`O sistema reprodutor da matriz não tem relevância na morte dos leitões.`,`Exclusivamente avaliar os ovários para cistos.`,`Examinar apenas a placenta sem avaliar o útero.`],resposta_correta:`A`,explicacao:`Em surtos de mortalidade neonatal em suínos, o exame do sistema reprodutor da matriz é essencial: endometrites, metrites, retenção de placenta e infecções uterinas podem causar sepia neonatal, infecções ascendentes e transmissão vertical de agentes como E. coli, Streptococcus e Clostridium.`},{id:`necr-049`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário 2023`,tipo:`concurso`,topico:`tecnica_necropsia_suina`,subtopico:`Exame do sistema urinário em suínos`,dificuldade:`facil`,enunciado:`Na necropsia de suínos, o rim suíno difere dos demais animais domésticos por apresentar:`,alternativas:[`Rim do tipo multilobar (compuesto), com múltiplos lobos fusionados, cápsula lisa, e cada lobo possui sua própria pirâmide renal e papila.`,`Rim do tipo unilobar, semelhante ao de cães.`,`Rim do tipo lobado, semelhante ao de bovinos neonatos.`,`Rim com apenas uma pirâmide renal (monopiramidal).`,`Não há diferenças significativas entre o rim suíno e o de outras espécies.`],resposta_correta:`A`,explicacao:`O rim suíno é do tipo multilobar (compuesto), com múltiplos lobos completamente fusionados, apresentando superfície externa lisa. Cada lobo possui sua pirâmide renal (papila), e a cápsula renal é lisa. Essa característica anatômica é importante para interpretação de lesões renais na necropsia.`},{id:`necr-050`,banca:`MAPA`,ano:2022,prova:`MAPA — Serviço Veterinário 2022`,tipo:`concurso`,topico:`tecnica_necropsia_suina`,subtopico:`Biossegurança em necropsia de suínos`,dificuldade:`dificil`,enunciado:`Em surtos de doenças de notificação obrigatória em suínos (ex: peste suína africana ou clássica), a necropsia em campo:`,alternativas:[`Deve ser evitada; o material deve ser coletado por profissionais credenciados e encaminhado a laboratório oficial, com biossegurança máxima e notificação imediata ao serviço veterinário oficial.`,`Pode ser realizada normalmente sem restrições.`,`Deve ser realizada apenas por médicos veterinários particulares.`,`Só é permitida após 7 dias do início do surto.`,`Deve ser realizada no mesmo local dos animais doentes.`],resposta_correta:`A`,explicacao:`Em suspeita de peste suína africana ou clássica, a necropsia em campo é contraindicada devido ao alto risco de disseminação viral. A coleta de material deve ser realizada por profissionais de laboratório oficial, com protocolos rígidos de biossegurança, e a notificação ao serviço veterinário oficial é obrigatória (doenças de notificação compulsória).`},{id:`necr-051`,banca:`USP`,ano:2021,prova:`USP — Concurso 2021`,tipo:`concurso`,topico:`tecnica_necropsia_suina`,subtopico:`Exame do sistema nervoso em suínos`,dificuldade:`dificil`,enunciado:`Na necropsia de suínos com sinais neurológicos, o diagnóstico diferencial deve incluir:`,alternativas:[`Meningite por Streptococcus suis, doença de Aujeszky (herpesvírus suíno), pseudoraiva, edema cerebral por E. coli (leitões), e intoxicações. O exame do SNC deve incluir encéfalo e medula espinhal.`,`Apenas intoxicações alimentares.`,`Exclusivamente deficiências nutricionais.`,`Não há doenças neurológicas relevantes em suínos.`,`Apenas traumas cranioencefálicos.`],resposta_correta:`A`,explicacao:`Os sinais neurológicos em suínos têm diagnóstico diferencial amplo: Streptococcus suis (meningoencefalite em leitões), doença de Aujeszky (Herpesvírus suíno tipo 1 — pseudoraiva), edema cerebral (E. coli verotoxigênica em leitões desmamados), raiva, intoxicações (sal, chumbo, organofosforados) e listeriose.`},{id:`necr-052`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Concurso 2022`,tipo:`concurso`,topico:`tecnica_necropsia_suina`,subtopico:`Exame da pele em suínos`,dificuldade:`medio`,enunciado:`O exame da pele na necropsia de suínos é especialmente importante para diagnóstico de:`,alternativas:[`Erisipela suína (losangos/pápulas romboidais na pele), peste suína (cianose em orelhas, extremidades), síndrome multissistêmica de definhamento (PMWS), dermatite e nefropatia suína (PDNS).`,`Apenas parasitoses externas como sarna.`,`Exclusivamente traumas e mordidas.`,`Não há relevância do exame cutâneo em suínos.`,`Apenas para avaliação de carcaças no abate.`],resposta_correta:`A`,explicacao:`A pele dos suínos é um importante indicador diagnóstico: erisipela (losangos/pápulas romboidais — "diamante"), peste suína (cianose em orelhas, abdômen, extremidades), PMWS/PDNS (dermatite necrótica), varíola suína, e sarna (Sarcoptes scabiei). O exame cutâneo deve ser parte rotineira da necropsia suína.`},{id:`necr-053`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`tecnica_necropsia_aviar`,subtopico:`Posição e abordagem na necropsia de aves`,dificuldade:`facil`,enunciado:`A posição padrão para necropsia de aves e a técnica de abertura das cavidades são:`,alternativas:[`Decúbito dorsal, com os membros tracionados lateralmente. A abertura é feita por incisão mediana ventral, com remoção da pele e musculatura, e exposição das cavidades torácica e abdominal, que em aves são comunicadas (celoma).`,`Decúbito lateral esquerdo, semelhante à necropsia de mamíferos.`,`Suspensão da ave pela cabeça.`,`Posição ventral com abertura pelo dorso.`,`Não há posição padrão para aves.`],resposta_correta:`A`,explicacao:`Em aves, a posição padrão é decúbito dorsal com os membros tracionados lateralmente. A particularidade anatômica é que as cavidades torácica e abdominal são comunicadas (celoma), sem diafragma. A abertura é feita por incisão mediana, umedecendo as penas para evitar contaminação por penugem.`},{id:`necr-054`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`tecnica_necropsia_aviar`,subtopico:`Exame do sistema digestório em aves`,dificuldade:`medio`,enunciado:`No exame do trato gastrointestinal de aves durante a necropsia, deve-se avaliar:`,alternativas:[`Papo (impactação, candidíase), esôfago, proventrículo (úlceras, parasitas), ventrículo muscular (moela — erosões, corpos estranhos), intestino delgado (coccidiose, enterite), cecos e reto/cloaca.`,`Apenas o intestino delgado.`,`Exclusivamente o papo e a moela.`,`Apenas o proventrículo em frangos de corte.`,`O trato digestório das aves não requer exame detalhado.`],resposta_correta:`A`,explicacao:`O trato gastrointestinal aviário é particularmente importante: papo (candidíase por Candida albicans, impactação), proventrículo (úlceras em aves aviárias, adenovírus), moela (corpos estranhos, erosões), intestino delgado (coccidiose — Eimeria spp., enterite por Clostridium, Marek), cecos (tiflite) e cloaca.`},{id:`necr-055`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso 2021`,tipo:`concurso`,topico:`tecnica_necropsia_aviar`,subtopico:`Exame do sistema respiratório em aves`,dificuldade:`medio`,enunciado:`O sistema respiratório das aves difere dos mamíferos por possuir:`,alternativas:[`Sacos aéreos (cranial, caudal, torácico cranial, torácico caudal, abdominal) que se comunicam com os pulmões, e pulmões fixos à parede torácica (não expansíveis). A necropsia deve avaliar todos os sacos aéreos.`,`Pulmões lobulados semelhantes aos de mamíferos.`,`Apenas traqueia e pulmões, sem estruturas acessórias.`,`Diafragma funcional que separa as cavidades torácica e abdominal.`,`Brônquios principais sem subdivisões.`],resposta_correta:`A`,explicacao:`O sistema respiratório aviário é único: pulmões compactos fixados à parede torácica dorsal, sem pleura, e cinco pares de sacos aéreos (cervical, cranial, caudal, torácico cranial, torácico caudal e abdominal) que permeiam grande parte da cavidade celomática. Os sacos aéreos são frequentemente acometidos por aspergilose, colibacilose e micoplasmose.`},{id:`necr-056`,banca:`UFMG`,ano:2023,prova:`UFMG — Concurso 2023`,tipo:`concurso`,topico:`tecnica_necropsia_aviar`,subtopico:`Exame do sistema imune em aves`,dificuldade:`dificil`,enunciado:`A avaliação do sistema imune na necropsia de aves inclui obrigatoriamente o exame de:`,alternativas:[`Bursa de Fabricius (fundamental em aves jovens — imunossupressão por IBD/doença de Gumboro), timo (atrofia em infecções virais), baço e linfonodos (nódulos linfoides cegais em galináceos).`,`Apenas o baço.`,`Exclusivamente a medula óssea.`,`Aves não possuem sistema imune que possa ser avaliado na necropsia.`,`Apenas o timo.`],resposta_correta:`A`,explicacao:`O sistema imune aviário tem particularidades: a Bursa de Fabricius (órgão linfóide exclusivo das aves, local de maturação dos linfócitos B) é essencial na avaliação de imunossupressão (doença de Gumboro/IBD). O timo, baço e nódulos linfoides cegais também devem ser examinados. A atrofia da Bursa indica imunossupressão.`},{id:`necr-057`,banca:`ENAV`,ano:2024,prova:`ENAV — Residência 2024`,tipo:`residencia`,topico:`tecnica_necropsia_aviar`,subtopico:`Exame do sistema reprodutor em aves`,dificuldade:`medio`,enunciado:`Na necropsia de poedeiras com queda de postura, o exame do sistema reprodutor deve incluir:`,alternativas:[`Avaliação do ovário (folículos atrésicos, hemorragia), oviduto (salpingite, peritonite de ovo, impacted oviduct), e verificar a presença de ovos na cavidade celomática.`,`Apenas a contagem de folículos ovarianos.`,`Exclusivamente o oviduto, sem avaliar o ovário.`,`Não é necessário examinar o sistema reprodutor em poedeiras.`,`Apenas verificar a presença de gema na cavidade abdominal.`],resposta_correta:`A`,explicacao:`A queda de postura em aves pode ter múltiplas causas infecciosas (Newcastle, bronquite infecciosa, micoplasmose, salmonelose). O exame reprodutor deve incluir ovário (degeneração folicular, hemorragia), oviduto (salpingite, secreção caseosa, peritonite de ovo — ovo retido na cavidade celomática), e cavidade celomática (peritonite vitelínica).`},{id:`necr-058`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário 2022`,tipo:`concurso`,topico:`tecnica_necropsia_aviar`,subtopico:`Exame do sistema musculoesquelético em aves`,dificuldade:`medio`,enunciado:`Na necropsia de frangos de corte com problemas de locomoção, deve-se avaliar:`,alternativas:[`Tendões (tenossinovite por reovírus), articulações (artrite estafilocócica, Mycoplasma synoviae), ossos (raquitismo, osteoporose, tibial dischondroplasia) e músculos (degeneração, palidez — deficiência de selênio/vitamina E).`,`Apenas os ossos longos para verificação de fraturas.`,`Exclusivamente as articulações do quadril.`,`Não é necessário exame musculoesquelético em aves.`,`Apenas os múculos peitorais.`],resposta_correta:`A`,explicacao:`Problemas locomotores em aves de corte são multifatoriais: tenossinovite viral (reovírus aviário), artrite (Staphylococcus, Mycoplasma synoviae), raquitismo (deficiência de vitamina D3, cálcio, fósforo), tibial dischondroplasia (distúrbio de crescimento ósseo) e miopatia (deficiência de selênio/vitamina E — doença do músculo branco).`},{id:`necr-059`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso 2020`,tipo:`concurso`,topico:`tecnica_necropsia_aviar`,subtopico:`Exame do sistema cardiovascular em aves`,dificuldade:`dificil`,enunciado:`Na necropsia de frangos de corte mortos por ascite (síndrome da hipertensão pulmonar), os achados característicos são:`,alternativas:[`Hidropericárdio (acúmulo de líquido no pericárdio), hepatomegalia congestiva (fígado em noz-moscada), ascite (líquido na cavidade celomática), e hipertrofia ventricular direita.`,`Hemopericárdio e ruptura cardíaca.`,`Miocardite necrosante e arritmias.`,`Pericardite fibrinosa e aderências.`,`Endocardite valvular e trombose.`],resposta_correta:`A`,explicacao:`A ascite em frangos de corte é causada por hipertensão pulmonar (geralmente associada a altitudes elevadas, frio, alta demanda metabólica). Os achados incluem: hidropericárdio, hepatomegalia congestiva (fígado com aspecto de noz-moscada), acúmulo de líquido seroso na cavidade celomática, e hipertrofia do ventrículo direito.`},{id:`necr-060`,banca:`MAPA`,ano:2023,prova:`MAPA — Serviço Veterinário 2023`,tipo:`concurso`,topico:`tecnica_necropsia_aviar`,subtopico:`Exame de aves em lote`,dificuldade:`facil`,enunciado:`Em necropsia de aves para vigilância sanitária em granjas, é recomendável:`,alternativas:[`Necropsiar pelo menos 5 a 10 aves por lote, incluindo aves mortas recentemente e aves sacrificadas com sinais clínicos, para obtenção de amostras representativas.`,`Necropsiar apenas 1 ave por lote.`,`Necropsiar apenas aves que morreram há mais de 24 horas.`,`Não é necessário necropsiar aves; basta a observação clínica.`,`Necropsiar exclusivamente aves sacrificadas.`],resposta_correta:`A`,explicacao:`Para representatividade diagnóstica em lotes avícolas, recomenda-se necropsiar de 5 a 10 aves, incluindo tanto aves mortas recentemente quanto aves sacrificadas que apresentam sinais clínicos. Deve-se coletar material de todos os órgãos com lesões e encaminhar a laboratório para diagnóstico complementar.`},{id:`necr-061`,banca:`CRMV`,ano:2021,prova:`CRMV — Exame 2021`,tipo:`crmv`,topico:`tecnica_necropsia_aviar`,subtopico:`Exame do sistema nervoso em aves`,dificuldade:`medio`,enunciado:`Na necropsia de aves com suspeita de doença de Marek, o exame deve incluir:`,alternativas:[`Exame de nervos periféricos (ciático, braquial, vagal — espessamento, edema), ovários, proventrículo, fígado, baço, rins e pele, com coleta de fragmentos para histopatologia e PCR.`,`Apenas o exame do encéfalo.`,`Exclusivamente os nervos periféricos.`,`Apenas ovários em poedeiras.`,`Não é possível diagnosticar Marek por necropsia.`],resposta_correta:`A`,explicacao:`A doença de Marek (herpesvírus aviário tipo 1) causa linfomatose em múltiplos órgãos. Na necropsia, observa-se: espessamento de nervos periféricos (ciático, braquial), infiltrados linfomatosos em ovários, proventrículo, fígado, baço, rins e pele. O diagnóstico é confirmado por histopatologia (linfócitos pleomórficos) e PCR.`},{id:`necr-062`,banca:`AVAMEC`,ano:2023,prova:`AVAMEC — Concurso 2023`,tipo:`concurso`,topico:`tecnica_necropsia_aviar`,subtopico:`Coleta de material em necropsia aviar`,dificuldade:`medio`,enunciado:`Para diagnóstico de influenza aviária (gripe aviária), a coleta adequada na necropsia inclui:`,alternativas:[`Swabs de cloaca e trato respiratório, fragmentos de pulmões, traqueia, intestino, fígado, rins e encéfalo, acondicionados em meio de transporte viral e enviados refrigerados ao laboratório oficial.`,`Apenas amostra de sangue post mortem.`,`Fragmentos de músculo peitoral apenas.`,`Apenas swabs de cloaca.`,`Exclusivamente fezes coletadas do chão do aviário.`],resposta_correta:`A`,explicacao:`Para diagnóstico de influenza aviária (doença de notificação obrigatória), a coleta deve ser realizada com biossegurança adequada. Mínimo de 5 aves por lote: swabs de cloaca e trato respiratório, fragmentos de pulmões, traqueia, intestino, fígado, rins e encéfalo. Material deve ser enviado em meio de transporte viral, refrigerado, ao laboratório oficial (LANAGRO).`},{id:`necr-063`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`tecnica_necropsia_peixes`,subtopico:`Abordagem e posição para necropsia de peixes`,dificuldade:`facil`,enunciado:`A técnica de necropsia em peixes difere dos mamíferos principalmente porque:`,alternativas:[`O exame externo inclui avaliação de brânquias, escamas, barbatanas, linha lateral e mucosa cutânea, e o exame interno requer remoção da parede opercular e branquial antes da abertura da cavidade celomática.`,`Peixes não possuem órgãos internos que possam ser examinados.`,`A necropsia de peixes é idêntica à de aves.`,`O exame é feito apenas por inspeção visual externa.`,`Apenas o exame microscópico é válido em peixes.`],resposta_correta:`A`,explicacao:`A necropsia de peixes tem particularidades anatômicas: exame externo inclui pele, escamas, barbatanas, olhos, abertura branquial e mucosa; o exame interno requer remoção do opérculo para avaliação das brânquias (estrutura lamelar), e abertura da cavidade celomática para exame de fígado, rins, baço, intestino, gônadas e vesícula gasosa.`},{id:`necr-064`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`tecnica_necropsia_peixes`,subtopico:`Exame das brânquias em peixes`,dificuldade:`medio`,enunciado:`Julgue o item sobre o exame branquial na necropsia de peixes:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`O exame das brânquias é fundamental na necropsia de peixes e deve incluir avaliação da coloração (palidez indica anemia, congestão indica irritação), consistência (mucosa, friável), presença de parasitas (Dactylogyrus, Gyrodactylus, Ichthyophthirius), necrose, hiperplasia epitelial e fusão de lamelas. As brânquias são o principal sítio de trocas gasosas e frequentemente o primeiro órgão afetado por problemas ambientais.`,explicacao:`As brânquias são órgãos vitais e altamente suscetíveis a lesões em peixes. Alterações branquiais estão associadas a parasitoses, infecções bacterianas (Flavobacterium columnare), problemas ambientais (amônia, nitrito, baixo oxigênio) e intoxicações. O exame deve ser microscópico (esfregaços e histologia).`},{id:`necr-065`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso 2021`,tipo:`concurso`,topico:`tecnica_necropsia_peixes`,subtopico:`Exame do sistema digestório em peixes`,dificuldade:`medio`,enunciado:`No exame do trato gastrointestinal de peixes durante a necropsia, deve-se avaliar:`,alternativas:[`Boca (lesões, parasitas), esôfago, estômago (presente em espécies carnívoras, ausente em herbívoras), intestino (comprimento varia com a dieta), fígado (hepatopancreas em algumas espécies) e vesícula biliar.`,`Apenas o intestino.`,`Exclusivamente o estômago.`,`Apenas o fígado e pâncreas.`,`O sistema digestório não é relevante em necropsia de peixes.`],resposta_correta:`A`,explicacao:`O trato gastrointestinal dos peixes varia conforme a espécie e dieta: carnívoros possuem estômago diferenciado; herbívoros podem não ter estômago. O intestino varia em comprimento (curto em carnívoros, longo em herbívoros). O fígado pode estar associado ao pâncreas (hepatopancreas). Parasitas intestinais são frequentes.`},{id:`necr-066`,banca:`UFMG`,ano:2020,prova:`UFMG — Concurso 2020`,tipo:`concurso`,topico:`tecnica_necropsia_peixes`,subtopico:`Exame da vesícula gasosa em peixes`,dificuldade:`medio`,enunciado:`A vesícula gasosa (bexiga natatória) na necropsia de peixes deve ser avaliada quanto a:`,alternativas:[`Volume (distensão ou colapso), integridade das paredes, presença de conteúdo líquido ou gasoso, e lesões (hemorragia, inflamação, parasitas). Alterações na vesícula gasosa afetam a flutuabilidade do peixe.`,`Apenas o volume de gás contido.`,`Não é necessário examinar a vesícula gasosa.`,`Exclusivamente em peixes ornamentais.`,`Apenas a coloração externa da vesícula.`],resposta_correta:`A`,explicacao:`A vesícula gasosa é órgão hidrostático que controla a flutuabilidade. Alterações (distensão, colapso, inflamação — aerocistite) causam problemas de flutuabilidade. Em necropsia, deve ser avaliada quanto a volume, integridade, conteúdo e lesões. A aerocistite é comum em carpas (Aeromonas, Pseudomonas).`},{id:`necr-067`,banca:`ENAV`,ano:2024,prova:`ENAV — Residência 2024`,tipo:`residencia`,topico:`tecnica_necropsia_peixes`,subtopico:`Exame dos rins em peixes`,dificuldade:`medio`,enunciado:`O rim dos peixes apresenta particularidades importantes para a necropsia, incluindo:`,alternativas:[`Rim anterior (cefálico/head kidney) que funciona como órgão hematopoiético e imune (equivalente à medula óssea de mamíferos), e rim posterior (trunk kidney) com função excretora. Ambos devem ser avaliados.`,`Rim único, semelhante ao de mamíferos.`,`Peixes não possuem rins funcionais.`,`Apenas o rim posterior é relevante.`,`O rim dos peixes é idêntico ao das aves.`],resposta_correta:`A`,explicacao:`O rim dos peixes é dividido em rim anterior (cefálico ou pronefro/head kidney), que é o principal órgão hematopoiético e imunológico (contém macrófagos e linfócitos), e rim posterior (mesonefro/trunk kidney), com função excretora. O rim anterior é frequentemente afetado por infecções sistêmicas (Aeromonas, Renibacterium salmoninarum — doença renal bacteriana).`},{id:`necr-068`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário Aquicultura 2023`,tipo:`concurso`,topico:`tecnica_necropsia_peixes`,subtopico:`Exame externo de peixes`,dificuldade:`facil`,enunciado:`O exame externo de peixes na necropsia deve incluir avaliação de:`,alternativas:[`Pele e muco (opacidade, excesso de muco, úlceras, hemorragias), escamas (aderência, perda), barbatanas (erosão, hemorragia, necrose), olhos (exoftalmia, catarata, opacidade de córnea), abertura branquial e nadadeiras.`,`Apenas a coloração da pele.`,`Exclusivamente as barbatanas.`,`Apenas os olhos e a boca.`,`O exame externo não é relevante em peixes.`],resposta_correta:`A`,explicacao:`O exame externo em peixes é crucial e deve incluir: pele e muco (lesões ulcerativas, hemorragias, excesso ou ausência de muco), escamas (aderência, perda), barbatanas (erosão — Columnaris, hemorragia), olhos (exoftalmia — comum em infecções sistêmicas, catarata), e cavidade oral (lesões, parasitas).`},{id:`necr-069`,banca:`MAPA`,ano:2022,prova:`MAPA — Serviço Veterinário Aquicultura 2022`,tipo:`concurso`,topico:`tecnica_necropsia_peixes`,subtopico:`Coleta de material em necropsia de peixes`,dificuldade:`medio`,enunciado:`Para diagnóstico de infecções bacterianas em peixes por necropsia, a coleta adequada de material inclui:`,alternativas:[`Esfregaços de rins e fígado para bacterioscopia, fragmentos de rins, fígado, baço, brânquias e intestino para bacteriologia e histopatologia, e água do tanque para análise microbiológica.`,`Apenas amostra de água do tanque.`,`Fragmentos de músculo apenas.`,`Apenas swabs de pele externa.`,`Exclusivamente amostra de sangue.`],resposta_correta:`A`,explicacao:`Para diagnóstico bacteriológico em peixes, devem ser coletados: esfregaços de rins e fígado (a bacterioscopia é rápida e útil), fragmentos de rins, fígado, baço, brânquias e intestino para cultivo bacteriológico e histopatologia. A água do tanque deve ser analisada para avaliação da qualidade e presença de patógenos.`},{id:`necr-070`,banca:`USP`,ano:2021,prova:`USP — Concurso 2021`,tipo:`concurso`,topico:`tecnica_necropsia_peixes`,subtopico:`Preservação de material de peixes`,dificuldade:`medio`,enunciado:`Para encaminhamento de peixes inteiros ao laboratório de diagnóstico, quando não é possível realizar a necropsia imediatamente, o procedimento correto é:`,alternativas:[`Acondicionar o peixe em saco plástico limpo, refrigerar (não congelar) e enviar ao laboratório o mais rápido possível. Peixes pequenos podem ser fixados inteiros em formol a 10%.`,`Congelar o peixe imediatamente em freezer doméstico.`,`Preservar em álcool 70% antes do envio.`,`Deixar em temperatura ambiente até o transporte.`,`Colocar em água com sal para preservação.`],resposta_correta:`A`,explicacao:`O congelamento causa artefatos teciduais (cristais de gelo) que comprometem a histopatologia. O ideal é refrigerar (4-8°C) e enviar rapidamente ao laboratório. Peixes pequenos podem ser fixados inteiros em formol a 10%. O transporte deve ser feito em caixa térmica com gelo, sem contato direto com a água.`},{id:`necr-071`,banca:`CRMV`,ano:2023,prova:`CRMV — Exame 2023`,tipo:`crmv`,topico:`tecnica_necropsia_peixes`,subtopico:`Exame do sistema nervoso em peixes`,dificuldade:`dificil`,enunciado:`O exame do sistema nervoso central em peixes durante a necropsia inclui:`,alternativas:[`Abertura do crânio com remoção do encéfalo (telencéfalo, cerebelo, bulbo olfatório), avaliação da medula espinhal e nervos periféricos. Lesões neurológicas podem indicar infecções virais (VHS, IHNV) ou deficiências nutricionais.`,`Apenas a medula espinhal.`,`Peixes não possuem sistema nervoso central examinável.`,`Exclusivamente os nervos cranianos.`,`O exame neurológico é dispensável em peixes.`],resposta_correta:`A`,explicacao:`O encéfalo dos peixes é relativamente simples mas examinável: telencéfalo, diencéfalo, cerebelo e bulbo olfatório. Deve ser removido com cuidado após abertura do crânio. A medula espinhal e nervos periféricos também devem ser avaliados. Lesões neurológicas em peixes podem indicar infecções virais (VHS, IHNV, IPNV), parasitas (Myxobolus cerebralis — doença de whirling) ou deficiências nutricionais.`},{id:`necr-072`,banca:`AVAMEC`,ano:2024,prova:`AVAMEC — Concurso 2024`,tipo:`concurso`,topico:`tecnica_necropsia_peixes`,subtopico:`Exame parasitológico em peixes`,dificuldade:`medio`,enunciado:`Na necropsia de peixes com suspeita de parasitose, o exame parasitológico deve incluir:`,alternativas:[`Raspado de pele e muco para ectoparasitas (Ichthyophthirius, Trichodina, Dactylogyrus), exame de brânquias (lamelas), raspado de mucosa intestinal para endoparasitas, e exame de órgãos internos (rins, fígado, cavidade abdominal).`,`Apenas raspado de pele.`,`Exclusivamente exame de fezes.`,`Apenas exame macroscópico das brânquias.`,`O exame parasitológico não é necessário na necropsia de peixes.`],resposta_correta:`A`,explicacao:`O exame parasitológico em peixes requer amostras de múltiplos sítios: pele e muco (Ichthyophthirius — "ponto branco", Trichodina, Costia, Chilodonella), brânquias (Dactylogyrus, Gyrodactylus, Ergasilus), intestino (cestóides, nematóides, trematóides) e órgãos internos (Myxozoa em rins e outros órgãos).`},{id:`necr-073`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`processos_pre_mortem`,subtopico:`Inspeção ante-mortem`,dificuldade:`facil`,enunciado:`A inspeção ante-mortem em animais de abate tem como objetivo:`,alternativas:[`Avaliar o estado de saúde do animal antes do abate, identificando animais doentes, debilitados, sob tratamento medicamentoso ou em condições que comprometam a aptidão para o consumo humano.`,`Determinar o peso vivo do animal para comercialização.`,`Avaliar apenas a idade do animal.`,`Verificar a raça e o padrão racial do animal.`,`Apenas confirmar a identificação do animal.`],resposta_correta:`A`,explicacao:`A inspeção ante-mortem é obrigatória nos estabelecimentos de abate e visa identificar animais com sinais de doença, debilidade, uso de medicamentos (período de carência), estresse excessivo ou condições que contraindiquem o abate para consumo humano. Animais suspeitos são separados para abate diferido ou inspeção complementar.`},{id:`necr-074`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário MAPA 2022`,tipo:`concurso`,topico:`processos_pre_mortem`,subtopico:`Sinais clínicos de animais ante-mortem`,dificuldade:`medio`,enunciado:`Julgue o item sobre sinais clínicos observados na inspeção ante-mortem:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`Na inspeção ante-mortem, sinais como prostração, ataxia, dispneia, febre, diarreia, secreções nasais ou oculares anormais, claudicação, edemas e alterações de comportamento devem ser observados. Animais com sinais de doença sistêmica, febre acima de 40,5°C ou em período de carência de medicamentos devem ser retidos.`,explicacao:`A inspeção ante-mortem deve ser minuciosa e incluir avaliação da marcha, estado nutricional, mucosas, temperatura corporal, frequência respiratória e cardíaca, secreções, presença de edemas e comportamento. Animais com sinais de enfermidade sistêmica são retidos para avaliação clínica complementar.`},{id:`necr-075`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário MAPA 2023`,tipo:`concurso`,topico:`processos_pre_mortem`,subtopico:`Triagem e isolamento ante-mortem`,dificuldade:`medio`,enunciado:`Na triagem ante-mortem de bovinos em abatedouro, animais com suspeita de febre aftosa devem:`,alternativas:[`Ser imediatamente isolados, com notificação ao serviço veterinário oficial, suspensão do abate de todo o lote e adoção de medidas de biossegurança para contenção da disseminação.`,`Ser abatidos normalmente, pois a febre aftosa não afeta a carcaça.`,`Ser apenas marcados e abatidos no final do dia.`,`Ser devolvidos ao proprietário sem notificação.`,`Ser abatidos em local separado, sem notificação oficial.`],resposta_correta:`A`,explicacao:`A febre aftosa é doença de notificação obrigatória com grande impacto comercial e sanitário. Em caso de suspeita, o animal deve ser isolado imediatamente, o serviço veterinário oficial (MAPA/CEVA) deve ser notificado, e o abate de todo o lote deve ser suspenso até investigação. Medidas de biossegurança (desinfecção, restrição de tráfego) são obrigatórias.`},{id:`necr-076`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso 2021`,tipo:`concurso`,topico:`processos_pre_mortem`,subtopico:`Período de carência e inspeção ante-mortem`,dificuldade:`dificil`,enunciado:`Sobre o período de carência na inspeção ante-mortem, é correto afirmar:`,alternativas:[`O período de carência é o tempo necessário para que o medicamento (antibiótico, anti-inflamatório, antiparasitário) seja eliminado do organismo do animal, garantindo que resíduos não estejam presentes nos tecidos comestíveis acima dos limites máximos permitidos (LMR).`,`O período de carência é o tempo que o animal deve permanecer em jejum antes do abate.`,`O período de carência é o intervalo entre a inspeção ante-mortem e o abate.`,`O período de carência se aplica apenas a hormônios de crescimento.`,`Não há regulamentação sobre períodos de carência no Brasil.`],resposta_correta:`A`,explicacao:`O período de carência (withdrawal period) é regulamentado pelo MAPA e varia conforme o medicamento, espécie animal e via de administração. Visa garantir que resíduos de medicamentos estejam abaixo dos Limites Máximos de Resíduos (LMR) nos tecidos comestíveis. Animais abatidos antes do período de carência têm a carcaça condenada.`},{id:`necr-077`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso 2020`,tipo:`concurso`,topico:`processos_pre_mortem`,subtopico:`Bem-estar e transporte pré-abate`,dificuldade:`medio`,enunciado:`O estresse de transporte e o manejo pré-abate afetam a qualidade da carne porque:`,alternativas:[`O estresse provoca depleção de glicogênio muscular, levando a alterações de pH (carne DFD — dark, firm, dry ou PSE — pale, soft, exudative), comprometendo cor, textura, maciez e vida de prateleira.`,`O estresse apenas altera o peso da carcaça.`,`O estresse não tem efeito comprovado na qualidade da carne.`,`Apenas a temperatura ambiente durante o transporte influencia a qualidade.`,`O estresse afeta apenas a coloração da gordura.`],resposta_correta:`A`,explicacao:`O estresse pré-abate depleta o glicogênio muscular, resultando em pH anormal post mortem: carne PSE (pálida, mole, exsudativa) quando há queda rápida de pH com temperatura ainda alta, e carne DFD (escura, firme, seca) quando o glicogênio é depletado antes do abate. Ambas comprometem a qualidade e a vida útil.`},{id:`necr-078`,banca:`UFMG`,ano:2023,prova:`UFMG — Concurso 2023`,tipo:`concurso`,topico:`processos_pre_mortem`,subtopico:`Jejum pré-abate`,dificuldade:`facil`,enunciado:`O jejum pré-abate em bovinos é recomendado por:`,alternativas:[`12 a 24 horas antes do abate, para reduzir o conteúdo gastrointestinal, facilitar o manejo no abate, reduzir contaminação fecal durante o evisceração e melhorar a qualidade da carcaça.`,`48 a 72 horas antes do abate, para perda de peso máxima.`,`Apenas 2 horas antes do abate.`,`Não é necessário jejum antes do abate.`,`O jejum é indicado apenas para suínos.`],resposta_correta:`A`,explicacao:`O jejum pré-abate em bovinos é de 12 a 24 horas, com acesso à água. Reduz o volume do trato gastrointestinal, minimiza o risco de contaminação durante a evisceração, facilita o trabalho no abate e contribui para melhor qualidade da carcaça. Jejum prolongado (>36h) causa estresse e perda de peso.`},{id:`necr-079`,banca:`MAPA`,ano:2022,prova:`MAPA — Serviço Veterinário 2022`,tipo:`concurso`,topico:`processos_pre_mortem`,subtopico:`Animais inapta para abate`,dificuldade:`medio`,enunciado:`De acordo com a legislação brasileira, são considerados INAPTOS para abate:`,alternativas:[`Animais doentes, debilitados, com febre, em período de carência de medicamentos, gestantes avançadas, recém-nascidos, e animais que apresentem sinais de enfermidade sistêmica ou estresse extremo.`,`Apenas animais com mais de 10 anos de idade.`,`Exclusivamente animais machos não castrados.`,`Apenas animais que não estejam identificados com brinco.`,`Qualquer animal apresentado para abate é apto.`],resposta_correta:`A`,explicacao:`O RIISPOA e instruções normativas do MAPA estabelecem critérios de inaptidão para abate: animais doentes, debilitados, febris, em período de carência, gestantes em estágio avançado, neonatos (bezerros com menos de 14 dias), animais sob estresse extremo ou com sinais de enfermidade que comprometam a aptidão para consumo.`},{id:`necr-080`,banca:`ENAV`,ano:2024,prova:`ENAV — Residência 2024`,tipo:`residencia`,topico:`processos_pre_mortem`,subtopico:`Atordoamento pré-abate`,dificuldade:`medio`,enunciado:`O atordoamento pré-abate é obrigatório no Brasil e tem como finalidade:`,alternativas:[`Promover a perda de consciência do animal antes da sangria, minimizando o sofrimento e o estresse, em conformidade com as normas de bem-estar animal e do SIF.`,`Acelerar o processo de sangria.`,`Melhorar a cor da carne.`,`Facilitar o depilamento do animal.`,`Reduzir o consumo de energia no abatedouro.`],resposta_correta:`A`,explicacao:`O atordoamento é obrigatório (Instrução Normativa MAPA) e visa promover a insensibilidade e perda de consciência antes da sangria, em atendimento às normas de bem-estar animal. Métodos incluem: percussão cativa (bovinos), eletronarcose (suínos, aves) e CO₂ (suínos). A insensibilidade deve ser verificada antes da sangria.`},{id:`necr-081`,banca:`CRMV`,ano:2021,prova:`CRMV — Exame 2021`,tipo:`crmv`,topico:`processos_pre_mortem`,subtopico:`Sinais de morte iminente`,dificuldade:`medio`,enunciado:`Os sinais de morte iminente em animais observados no período pré-mortem incluem:`,alternativas:[`Agonia (movimentos respiratórios irregulares, convulsões terminais), perda de reflexos (corneal, pupilar), cianose progressiva, relaxamento dos esfíncteres e ausência de pulso.`,`Apenas parada cardíaca.`,`Exclusivamente perda de consciência.`,`Apenas ausência de movimentos respiratórios.`,`A morte é instantânea e não há sinais premonitórios.`],resposta_correta:`A`,explicacao:`A morte é um processo e não um evento instantâneo. Os sinais de morte iminente incluem: fase de agonia (respiração de Cheyne-Stokes, convulsões), perda progressiva de reflexos (corneal, pupilar, de deglutição), cianose crescente, relaxamento dos esfíncteres, e por fim, parada cardíaca e respiratória confirmada.`},{id:`necr-082`,banca:`AVAMEC`,ano:2023,prova:`AVAMEC — Concurso 2023`,tipo:`concurso`,topico:`processos_pre_mortem`,subtopico:`Confirmação da morte`,dificuldade:`facil`,enunciado:`Para confirmação da morte animal, os métodos incluem:`,alternativas:[`Ausência de batimentos cardíacos (ausculta), ausência de movimentos respiratórios, ausência de reflexos (corneal, pupilar, de dor), fixação do globo ocular e cianose das mucosas.`,`Apenas ausência de pulso.`,`Exclusivamente a parada respiratória.`,`Apenas o relaxamento muscular.`,`A confirmação da morte só pode ser feita por eletrocardiograma.`],resposta_correta:`A`,explicacao:`A confirmação da morte requer avaliação de múltiplos parâmetros: ausência de batimentos cardíacos (ausculta bilateral), ausência de movimentos respiratórios, ausência de reflexos (corneal, pupilar, de dor, faríngeo), cianose de mucosas, e hipostasia (livor mortis). A confirmação tardia (rigor mortis) é tardia e menos útil clinicamente.`},{id:`necr-083`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`processos_post_mortem`,subtopico:`Rigor mortis`,dificuldade:`facil`,enunciado:`O rigor mortis é definido como:`,alternativas:[`A rigidez cadavérica resultante da contração permanente das fibras musculares devido à depleção de ATP e formação de complexos actina-miosina estáveis, ocorrendo geralmente entre 2 a 8 horas após a morte em temperatura ambiente.`,`O resfriamento progressivo do cadáver após a morte.`,`A coloração violácea das mucosas após a morte.`,`O início da decomposição dos tecidos.`,`O acúmulo de gases na cavidade abdominal.`],resposta_correta:`A`,explicacao:`O rigor mortis é consequência da depleção de ATP no músculo post mortem, permitindo a formação de pontes permanentes actina-miosina. Inicia-se geralmente 2-4 horas após a morte, atinge plenitude em 6-12 horas e se resolve em 24-72 horas com o início da autólise. É importante para estimar o tempo de morte.`},{id:`necr-084`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`processos_post_mortem`,subtopico:`Livor mortis`,dificuldade:`medio`,enunciado:`Julgue o item sobre livor mortis (lividez cadavérica):`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`O livor mortis é o acúmulo de sangue nas partes declives do cadáver devido à ação gravitacional, após a parada circulatória. Inicia-se 30 minutos a 2 horas após a morte, fixa-se entre 6 a 12 horas e é útil para determinar a posição do cadáver após a morte. A coloração é vermelho-violácea em animais de pele clara.`,explicacao:`O livor mortis (hipostasia cadavérica) resulta do acúmulo de sangue nas partes mais baixas do cadáver por gravidade. É um dos primeiros sinais post mortem, útil para estimar o tempo de morte e verificar se o cadáver foi movido após o óbito. Em animais de pele escura, a visualização é mais difícil.`},{id:`necr-085`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso 2021`,tipo:`concurso`,topico:`processos_post_mortem`,subtopico:`Algor mortis`,dificuldade:`medio`,enunciado:`O algor mortis (resfriamento cadavérico) é importante na necropsia porque:`,alternativas:[`A taxa de resfriamento do cadáver pode ser utilizada para estimar o intervalo post mortem (tempo desde a morte), considerando a temperatura ambiente, massa corporal e vestimenta/abrigo do animal.`,`O resfriamento indica que o animal está em estado de coma.`,`O algor mortis não tem valor diagnóstico.`,`O resfriamento ocorre imediatamente após a morte.`,`A temperatura corporal permanece constante após a morte por 48 horas.`],resposta_correta:`A`,explicacao:`O algor mortis é a perda progressiva de calor corporal post mortem. A temperatura corporal diminui aproximadamente 0,8-1,0°C por hora em condições normais, dependendo da massa corporal, temperatura ambiente, vestimenta e umidade. A medição retal da temperatura post mortem é útil para estimar o tempo de morte.`},{id:`necr-086`,banca:`UFMG`,ano:2023,prova:`UFMG — Concurso 2023`,tipo:`concurso`,topico:`processos_post_mortem`,subtopico:`Autólise`,dificuldade:`medio`,enunciado:`A autólise é o processo de degradação tecidual:`,alternativas:[`Causada por enzimas endógenas (lisossomais) das próprias células do cadáver, independentemente de bactérias, resultando em amolecimento dos tecidos e perda da arquitetura celular.`,`Causada exclusivamente por bactérias do trato gastrointestinal.`,`Um processo que ocorre apenas em temperaturas acima de 37°C.`,`Idêntica à putrefação.`,`Um processo que não afeta a interpretação histológica.`],resposta_correta:`A`,explicacao:`A autólise é a degradação enzimática endógena (enzimas lisossomais como catepsinas, lipases, fosfolipases) das células do cadáver após a morte. Distingue-se da putrefação (ação bacteriana). A autólise é mais rápida em órgãos ricos em enzimas digestivas (pâncreas, estômago, intestino) e é agravada por temperaturas elevadas.`},{id:`necr-087`,banca:`ENAV`,ano:2024,prova:`ENAV — Residência 2024`,tipo:`residencia`,topico:`processos_post_mortem`,subtopico:`Putrefação`,dificuldade:`medio`,enunciado:`A putrefação é caracterizada por:`,alternativas:[`Decomposição dos tecidos por ação bacteriana (principalmente anaeróbios do trato gastrointestinal), com produção de gases (H₂S, NH₃, metano), descoloração esverdeada do abdômen e crepitação dos tecidos.`,`Resfriamento progressivo do cadáver.`,`Rigidez dos músculos esqueléticos.`,`Acúmulo de sangue nas partes declives.`,`Preservação dos tecidos por desidratação.`],resposta_correta:`A`,explicacao:`A putrefação é a decomposição bacteriana dos tecidos, iniciando-se geralmente no trato gastrointestinal (maior concentração bacteriana). Caracteriza-se por: coloração esverdeada abdominal (formação de sulfometahemoglobina), produção de gases (crepitação, distensão abdominal), desprendimento de epiderme, e odor fétido (H₂S, mercaptanas, amônia).`},{id:`necr-088`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário 2022`,tipo:`concurso`,topico:`processos_post_mortem`,subtopico:`Sequência dos fenômenos cadavéricos`,dificuldade:`facil`,enunciado:`A sequência cronológica dos fenômenos cadavéricos imediatos é:`,alternativas:[`Resfriamento (algor mortis), lividez (livor mortis), rigidez (rigor mortis), seguidos de autólise e putrefação.`,`Rigor mortis, algor mortis, livor mortis.`,`Putrefação, autólise, rigor mortis.`,`Livor mortis, putrefação, algor mortis.`,`Não há sequência definida; todos ocorrem simultaneamente.`],resposta_correta:`A`,explicacao:`Os fenômenos cadavéricos imediatos seguem uma sequência temporal: algor mortis (resfriamento — início imediato), livor mortis (lividez — 30min-2h), rigor mortis (rigidez — 2-8h). Posteriormente ocorrem os fenômenos tardios: autólise, putrefação, mumificação, adipocira e fossilização, dependendo das condições ambientais.`},{id:`necr-089`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso 2020`,tipo:`concurso`,topico:`processos_post_mortem`,subtopico:`Fenômenos cadavéricos tardios`,dificuldade:`dificil`,enunciado:`Os fenômenos cadavéricos tardios incluem:`,alternativas:[`Mumificação (desidratação em ambientes secos e quentes), adipocira (saponificação em ambientes úmidos), fossilização (mineralização em solos ricos em minerais) e decomposição completa.`,`Apenas mumificação.`,`Exclusivamente putrefação avançada.`,`Apenas adipocira.`,`Os fenômenos tardios são apenas a continuação da autólise.`],resposta_correta:`A`,explicacao:`Os fenômenos cadavéricos tardios dependem das condições ambientais: mumificação (clima seco e quente — desidratação e conservação), adipocira (ambiente úmido e anaeróbico — saponificação da gordura), fossilização (solos ricos em cálcio e minerais), e decomposição completa (retorno ao ambiente). Cada fenômeno tem valor para estimar tempo e condições de morte.`},{id:`necr-090`,banca:`CRMV`,ano:2023,prova:`CRMV — Exame 2023`,tipo:`crmv`,topico:`processos_post_mortem`,subtopico:`Artefatos post mortem`,dificuldade:`dificil`,enunciado:`Na interpretação dos achados de necropsia, é fundamental diferenciar lesões ante mortem de artefatos post mortem. São exemplos de artefatos post mortem:`,alternativas:[`Congestão passiva gravitacional (hipostasia), hemólise post mortem (hemoglobina em soro), autólise gástrica (digestão da mucosa), e hemorragia por ruptura de vasos durante manipulação do cadáver.`,`Úlceras gástricas, pneumonia e nefrite.`,`Abscessos, granulomas e neoplasias.`,`Fraturas ósseas, luxações e deslocamentos.`,`Endocardite, miocardite e pericardite.`],resposta_correta:`A`,explicacao:`Artefatos post mortem são alterações que ocorrem após a morte e podem ser confundidas com lesões ante mortem: hipostasia (confundida com congestão/hemorragia), hemólise (confundida com hemorragia), autólise (confundida com necrose), digestão post mortem da mucosa gástrica, e lesões iatrogênicas durante a manipulação do cadáver.`},{id:`necr-091`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Concurso 2022`,tipo:`concurso`,topico:`processos_post_mortem`,subtopico:`Estimativa do intervalo post mortem`,dificuldade:`medio`,enunciado:`Para estimar o intervalo post mortem (tempo desde a morte) em animais, os principais parâmetros utilizados são:`,alternativas:[`Temperatura corporal (algor mortis), grau de rigor mortis, presença e extensão do livor mortis, estágio de autólise e putrefação, e presença de insetos (entomologia forense).`,`Apenas a temperatura corporal.`,`Exclusivamente o grau de rigidez muscular.`,`Apenas a presença de moscas e insetos.`,`O intervalo post mortem não pode ser estimado.`],resposta_correta:`A`,explicacao:`A estimativa do intervalo post mortem utiliza múltiplos parâmetros combinados: algor mortis (taxa de resfriamento), rigor mortis (início, plenitude e resolução), livor mortis (aparecimento e fixação), grau de autólise e putrefação, e entomologia forense (sucessão de insetos no cadáver). Nenhum parâmetro isolado é suficiente.`},{id:`necr-092`,banca:`USP`,ano:2021,prova:`USP — Concurso 2021`,tipo:`concurso`,topico:`processos_post_mortem`,subtopico:`Efeito da temperatura nos fenômenos cadavéricos`,dificuldade:`medio`,enunciado:`A temperatura ambiente influencia os fenômenos cadavéricos porque:`,alternativas:[`Temperaturas elevadas aceleram a autólise e putrefação, enquanto temperaturas baixas (refrigeração) retardam esses processos, e o congelamento pode preservar os tecidos por longos períodos, porém com artefatos de cristais de gelo.`,`A temperatura não influencia os fenômenos cadavéricos.`,`Apenas temperaturas acima de 60°C afetam os processos.`,`O congelamento destrói completamente os tecidos.`,`Temperaturas baixas aceleram a putrefação.`],resposta_correta:`A`,explicacao:`A temperatura é o principal fator que modula a velocidade dos fenômenos cadavéricos: temperaturas elevadas (>25°C) aceleram autólise e putrefação; temperaturas de refrigeração (4-8°C) retardam significativamente; congelamento (-20°C) interrompe a maioria dos processos, mas causa artefatos teciduais (cristais de gelo intracelulares).`},{id:`necr-093`,banca:`MAPA`,ano:2023,prova:`MAPA — Serviço Veterinário 2023`,tipo:`concurso`,topico:`processos_post_mortem`,subtopico:`Importância dos fenômenos cadavéricos na inspeção`,dificuldade:`facil`,enunciado:`O conhecimento dos fenômenos cadavéricos é essencial para o médico veterinário do SIF porque:`,alternativas:[`Permite diferenciar alterações post mortem de lesões ante mortem, evitando condenações indevidas de carcaças e garantindo a correta interpretação dos achados na inspeção.`,`Apenas para determinar o tempo de morte do animal.`,`Não tem aplicação na inspeção de produtos de origem animal.`,`É relevante apenas para fins acadêmicos.`,`Serve apenas para diagnóstico forense.`],resposta_correta:`A`,explicacao:`Na inspeção de produtos de origem animal, o conhecimento dos fenômenos cadavéricos é fundamental para: não confundir hipostasia com congestão patológica, autólise com necrose, ou hemólise post mortem com hemorragia ante mortem. Essa distinção evita condenações indevidas e garante a segurança e qualidade do produto inspecionado.`},{id:`necr-094`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`coleta_preservacao_material`,subtopico:`Fixação de tecidos para histopatologia`,dificuldade:`facil`,enunciado:`O fixador mais utilizado para histopatologia na necropsia veterinária é:`,alternativas:[`Formol tamponado a 10% (formaldeído a 4%), que preserva a arquitetura tecidual e permite diversas colorações especiais e técnicas imuno-histoquímicas.`,`Álcool etílico absoluto.`,`Ácido acético glacial.`,`Glutaraldeído a 2,5% (para microscopia eletrônica).`,`Líquido de Bouin.`],resposta_correta:`A`,explicacao:`O formol tamponado a 10% (solução de formaldeído a 4% em tampão fosfato) é o fixador padrão para histopatologia. Penetra adequadamente nos tecidos (1mm/h), preserva a arquitetura celular e tecidual, e é compatível com a maioria das colorações (H&E, PAS, Tricrômio de Masson) e técnicas imuno-histoquímicas.`},{id:`necr-095`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`coleta_preservacao_material`,subtopico:`Coleta de material para bacteriologia`,dificuldade:`medio`,enunciado:`Julgue o item sobre coleta de material para bacteriologia na necropsia:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`Para bacteriologia, a coleta deve ser realizada com instrumentos estéreis (alça de platina flambada, bisturi estéril, swabs estéreis), antes da manipulação excessiva dos órgãos, de áreas com lesão ativa (necrose, abscesso, borda de úlcera), e o material deve ser inoculado em meios de transporte adequados (Stuart, Cary-Blair) ou semeados diretamente em meios de cultura, mantidos refrigerados (4°C).`,explicacao:`A técnica asséptica é fundamental para bacteriologia. A coleta deve ser feita antes da contaminação por manipulação, de áreas com lesão ativa e tecido viável (não necrótico central). Swabs devem ser mantidos em meio de transporte. Fragmentos podem ser enviados em soro fisiológico estéril. A refrigeração (não congelamento) preserva a viabilidade bacteriana.`},{id:`necr-096`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso 2021`,tipo:`concurso`,topico:`coleta_preservacao_material`,subtopico:`Coleta de material para virologia`,dificuldade:`medio`,enunciado:`Para diagnóstico virológico na necropsia, o material deve ser:`,alternativas:[`Coletado assepticamente de órgãos com lesão fresca, acondicionado em meio de transporte viral (meio Eagle, solução salina com antibióticos), mantido refrigerado (4°C) ou congelado (-70°C), e encaminhado rapidamente ao laboratório.`,`Fixado em formol a 10% imediatamente após a coleta.`,`Preservado em álcool 70%.`,`Coletado apenas de cadáveres em avançado estado de decomposição.`,`Acondicionado em sacos plásticos sem refrigeração.`],resposta_correta:`A`,explicacao:`O material para virologia deve manter a viabilidade viral: coleta asseptica, acondicionamento em meio de transporte viral (para proteger o vírus da dessecação e contaminação bacteriana), refrigeração (4°C) para transporte em até 48h ou congelamento (-70°C) para armazenamento prolongado. O formol destrói a infectividade viral.`},{id:`necr-097`,banca:`UFMG`,ano:2020,prova:`UFMG — Concurso 2020`,tipo:`concurso`,topico:`coleta_preservacao_material`,subtopico:`Coleta de material para toxicologia`,dificuldade:`dificil`,enunciado:`Em caso de suspeita de intoxicação, a coleta de material para toxicologia deve incluir:`,alternativas:[`Conteúdo gástrico e intestinal, fígado, rins, sangue (com e sem anticoagulante), urina, e água/alimento suspeito, acondicionados em recipientes limpos e lacrados, sem formol, mantidos refrigerados.`,`Apenas amostra de sangue com anticoagulante.`,`Fragmentos fixados em formol a 10%.`,`Apenas conteúdo gástrico congelado.`,`Exclusivamente amostra de água do local.`],resposta_correta:`A`,explicacao:`Para toxicologia, o material NÃO deve ser fixado em formol (interfere na análise química). Devem ser coletados: conteúdo gástrico/intestinal, fígado, rins, sangue (com e sem anticoagulante), urina, e qualquer material suspeito (água, alimento, plantas). Acondicionar em recipientes limpos, lacrados, refrigerados (não congelar, exceto por orientação laboratorial).`},{id:`necr-098`,banca:`ENAV`,ano:2024,prova:`ENAV — Residência 2024`,tipo:`residencia`,topico:`coleta_preservacao_material`,subtopico:`Coleta de material para parasitologia`,dificuldade:`facil`,enunciado:`Para diagnóstico parasitológico na necropsia, a coleta deve incluir:`,alternativas:[`Fezes (frescas e preservadas em formol a 10%), conteúdo intestinal, fragmentos de órgãos parasitados (fígado, pulmões, intestino), e ectoparasitas (preservados em álcool 70%), com identificação adequada.`,`Apenas amostra de fezes frescas.`,`Exclusivamente fragmentos de fígado fixados em formol.`,`Apenas swabs retais.`,`Material apenas de animais vivos.`],resposta_correta:`A`,explicacao:`A coleta parasitolológica na necropsia deve ser ampla: fezes frescas e preservadas (formol a 10% para ovos e cistos), conteúdo intestinal (vermes adultos), fragmentos de órgãos parasitados (fígado para Fasciola, pulmões para Dictyocaulus), e ectoparasitas (em álcool 70% para preservação da morfologia). A identificação do hospedeiro e local é essencial.`},{id:`necr-099`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário 2023`,tipo:`concurso`,topico:`coleta_preservacao_material`,subtopico:`Envio de material ao laboratório`,dificuldade:`medio`,enunciado:`O envio de material de necropsia ao laboratório de diagnóstico deve seguir:`,alternativas:[`Identificação clara (espécie, animal, data, órgão), acondicionamento adequado (formol para histologia, meio de transporte para bacteriologia, gelo para virologia), cadeia de frio, formulário com dados clínicos e epidemiológicos, e transporte rápido.`,`Apenas o material acondicionado em saco plástico comum.`,`Enviar os órgãos inteiros sem fixação, em temperatura ambiente.`,`Apenas o formulário de requisição, sem o material biológico.`,`Não é necessário formulário; o laboratório identificará o material.`],resposta_correta:`A`,explicacao:`O envio de material ao laboratório requer: 1) identificação completa de cada amostra; 2) acondicionamento adequado conforme o exame (formol para histologia, meio de transporte para bacteriologia, gelo para virologia); 3) cadeia de frio; 4) formulário de requisição com histórico clínico e epidemiológico; 5) transporte rápido.`},{id:`necr-100`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso 2020`,tipo:`concurso`,topico:`coleta_preservacao_material`,subtopico:`Congelamento de amostras`,dificuldade:`medio`,enunciado:`O congelamento de amostras de tecido para diagnóstico:`,alternativas:[`Deve ser evitado para histopatologia (causa artefatos de cristais de gelo), mas é indicado para armazenamento prolongado de amostras para toxicologia, virologia (a -70°C) e molecular (PCR), quando não é possível processamento imediato.`,`É o método de preservação ideal para todas as finalidades.`,`Deve ser feito em freezer doméstico (-18°C) para todas as amostras.`,`Não é recomendado em nenhuma situação.`,`É indicado apenas para amostras de sangue.`],resposta_correta:`A`,explicacao:`O congelamento é contraindicado para histopatologia (cristais de gelo destroem a arquitetura tecidual), mas indicado para: toxicologia (preserva compostos químicos), virologia (-70°C preserva infectividade viral), e técnicas moleculares (PCR, sequenciamento — preserva DNA/RNA). Freezer doméstico (-18°C) é adequado para toxicologia; ultrafreezer (-70°C) é necessário para virologia.`},{id:`necr-101`,banca:`CRMV`,ano:2021,prova:`CRMV — Exame 2021`,tipo:`crmv`,topico:`coleta_preservacao_material`,subtopico:`Coleta de sangue post mortem`,dificuldade:`medio`,enunciado:`A coleta de sangue post mortem para diagnóstico:`,alternativas:[`Deve ser realizada o mais precocemente possível após a morte, preferencialmente do coração (ventrículo direito) ou grandes vasos, com seringa e agulha estéreis, e separar alíquota com e sem anticoagulante.`,`Só é possível nas primeiras 5 minutos após a morte.`,`Não tem valor diagnóstico após a morte.`,`Deve ser feita apenas de veias periféricas.`,`O sangue post mortem deve ser sempre fixado em formol.`],resposta_correta:`A`,explicacao:`O sangue post mortem pode ser coletado nas primeiras horas após a morte, antes da hemólise significativa. A punção cardíaca (ventrículo direito) ou de grandes vasos (aorta, veia cava) é o método mais prático. Deve-se separar alíquotas: com anticoagulante (EDTA ou heparina — para hemograma, PCR) e sem anticoagulante (para sorologia, bioquímica).`},{id:`necr-102`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Concurso 2022`,tipo:`concurso`,topico:`coleta_preservacao_material`,subtopico:`Técnicas de impressão (imprint)`,dificuldade:`medio`,enunciado:`A técnica de impressão (imprint) na necropsia consiste em:`,alternativas:[`Pressionar a superfície de corte de um órgão fresco sobre uma lâmina de vidro limpa, fixar e corar (Diff-Quick, Giemsa, Gram) para avaliação citológica rápida, útil para diagnóstico preliminar de infecções, neoplasias e inflamações.`,`Realizar fotografia dos órgãos com lesão.`,`Imprimir o laudo de necropsia em papel.`,`Pressionar a lâmina sobre o órgão para coleta de DNA.`,`Realizar cultura bacteriológica direta do órgão.`],resposta_correta:`A`,explicacao:`O imprint (impressão ou esfregaço de órgão) é técnica citológica rápida e simples: a superfície de corte do órgão é pressionada suavemente sobre lâmina de vidro, fixada (metanol ou calor) e corada. Permite avaliação imediata de células inflamatórias, neoplásicas, bactérias, fungos e parasitas. É especialmente útil para diagnóstico preliminar em campo.`},{id:`necr-103`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`diagnostico_necroscopico`,subtopico:`Interpretação de lesões macroscópicas`,dificuldade:`facil`,enunciado:`Na interpretação das lesões macroscópicas durante a necropsia, o médico veterinário deve:`,alternativas:[`Descrever sistematicamente cada lesão quanto à localização, tamanho, forma, cor, consistência, bordas, e relação com estruturas adjacentes, antes de formular hipóteses diagnósticas.`,`Apenas fotografar as lesões sem descrição escrita.`,`Classificar as lesões como benignas ou malignas imediatamente.`,`Descrever apenas as lesões que parecem mais graves.`,`Formular o diagnóstico antes de completar o exame.`],resposta_correta:`A`,explicacao:`A interpretação das lesões na necropsia requer descrição objetiva e sistemática (topografia, dimensões, forma, cor, consistência, limites) antes da interpretação subjetiva. O diagnóstico anatomopatológico é formulado após a descrição de todas as lesões e correlação com o histórico clínico e epidemiológico.`},{id:`necr-104`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`diagnostico_necroscopico`,subtopico:`Diagnóstico diferencial na necropsia`,dificuldade:`medio`,enunciado:`O diagnóstico diferencial na necropsia é importante porque:`,alternativas:[`Diversas doenças podem produzir lesões macroscópicas semelhantes, e a formulação de hipóteses diferenciais orienta a coleta de material para exames complementares que confirmarão o diagnóstico definitivo.`,`Apenas uma única doença pode causar determinada lesão.`,`O diagnóstico diferencial é necessário apenas em casos de dúvida.`,`O diagnóstico macroscópico é sempre definitivo.`,`O diagnóstico diferencial é dispensável quando há exame histopatológico.`],resposta_correta:`A`,explicacao:`O diagnóstico diferencial é essencial na necropsia pois lesões semelhantes podem ter causas distintas: necrose hepática pode ser viral (IBR, leptospirose), tóxica (plantas, aflatoxinas) ou isquêmica. A formulação de hipóteses diferenciais orienta a coleta adequada de material e a solicitação de exames complementares (histopatologia, bacteriologia, PCR).`},{id:`necr-105`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso 2021`,tipo:`concurso`,topico:`diagnostico_necroscopico`,subtopico:`Laudo necroscópico`,dificuldade:`medio`,enunciado:`A conclusão do laudo de necropsia deve:`,alternativas:[`Basear-se exclusivamente nos achados de necropsia e exames complementares, apresentando o diagnóstico anatomopatológico e a causa provável da morte, sem especulações clínicas sem respaldo nos achados.`,`Incluir apenas a opinião do veterinário sem descrição dos achados.`,`Ser sempre conclusiva, mesmo na ausência de lesões significativas.`,`Limitar-se a citar exames complementares sem interpretação.`,`Incluir apenas a identificação do animal.`],resposta_correta:`A`,explicacao:`A conclusão do laudo necroscópico deve ser fundamentada nos achados objetivos (macroscópicos e complementares), apresentando: 1) diagnóstico anatomopatológico (descrição das lesões); 2) diagnóstico etiológico (quando possível); 3) causa provável da morte. Na ausência de lesões significativas, deve-se registrar "causa mortis não determinada" e sugerir exames complementares.`},{id:`necr-106`,banca:`UFMG`,ano:2023,prova:`UFMG — Concurso 2023`,tipo:`concurso`,topico:`diagnostico_necroscopico`,subtopico:`Exames complementares ao diagnóstico necroscópico`,dificuldade:`medio`,enunciado:`Os exames complementares mais frequentemente solicitados após a necropsia incluem:`,alternativas:[`Histopatologia (H&E e colorações especiais), bacteriologia, virologia, parasitologia, toxicologia, imuno-histoquímica e PCR.`,`Apenas histopatologia.`,`Exclusivamente bacteriologia.`,`Apenas hemograma post mortem.`,`Exames de imagem (raio-X, ultrassonografia).`],resposta_correta:`A`,explicacao:`O diagnóstico necroscópico é frequentemente complementado por: histopatologia (base do diagnóstico anatomopatológico), bacteriologia (isolamento e identificação de bactérias), virologia (isolamento viral, PCR), parasitologia (identificação de parasitas), toxicologia (dosagem de toxinas), imuno-histoquímica (detecção de antígenos em tecidos) e biologia molecular (PCR, sequenciamento).`},{id:`necr-107`,banca:`ENAV`,ano:2024,prova:`ENAV — Residência 2024`,tipo:`residencia`,topico:`diagnostico_necroscopico`,subtopico:`Lesões vasculares na necropsia`,dificuldade:`dificil`,enunciado:`Na interpretação de lesões vasculares durante a necropsia, a tromboembolia pulmonar é caracterizada por:`,alternativas:[`Presença de trombos (coágulos antemortem aderidos à parede vascular) nas artérias pulmonares, frequentemente originados de trombose venosa profunda (membros, pelve), causando morte súbita por obstrução do fluxo pulmonar.`,`Coágulos post mortem soltos nos vasos pulmonares.`,`Apenas edema pulmonar sem obstrução vascular.`,`Hemorragia alveolar difusa.`,`Infarto do miocárdio.`],resposta_correta:`A`,explicacao:`A tromboembolia pulmonar é causa importante de morte súbita. Os trombos antemortem diferem dos coágulos post mortem por serem firmes, aderidos à parede vascular, com estrutura laminada (linhas de Zahn) e cor variável (vermelho-branco). Frequentemente originam-se de trombose venosa profunda (pelve, membros posteriores) em animais imobilizados ou com coagulopatias.`},{id:`necr-108`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário 2022`,tipo:`concurso`,topico:`diagnostico_necroscopico`,subtopico:`Lesões de neoplasia na necropsia`,dificuldade:`medio`,enunciado:`Na necropsia, lesões sugestivas de neoplasia maligna incluem:`,alternativas:[`Massas infiltrativas com bordas mal definidas, necrose central (por isquemia), hemorragia, metástases em órgãos à distância e invasão de tecidos adjacentes.`,`Massas encapsuladas com bordas bem definidas.`,`Nódulos pequenos e múltiplos com aspecto uniforme.`,`Lesões superficiais sem invasão tecidual.`,`Cistos preenchidos por líquido claro.`],resposta_correta:`A`,explicacao:`As características macroscópicas que sugerem malignidade incluem: crescimento rápido, bordas infiltrativas irregulares, necrose central (por crescimento mais rápido que a vascularização), hemorragia (invasão vascular), metástases (disseminação a distância), e invasão de tecidos adjacentes. A confirmação é histopatológica.`},{id:`necr-109`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso 2020`,tipo:`concurso`,topico:`diagnostico_necroscopico`,subtopico:`Lesões de inflamação na necropsia`,dificuldade:`facil`,enunciado:`As principais lesões inflamatórias identificáveis macroscopicamente na necropsia são:`,alternativas:[`Exsudato fibrinoso (membranas fibrinosas), supuração (abscesso, empiema), granulomas (nódulos firmes), edema, hiperemia e necrose inflamatória.`,`Apenas edema e hiperemia.`,`Exclusivamente abscessos.`,`Apenas granulomas caseosos.`,`Somente necrose seca.`],resposta_correta:`A`,explicacao:`As lesões inflamatórias macroscópicas incluem: exsudato fibrinoso (pericardite, pleurite, peritonite fibrinosa), supuração (abscesso — coleção de pus encapsulada; empiema — pus em cavidade), granulomas (resposta a agentes persistentes — tuberculose, corpo estranho), edema (acúmulo de líquido extravascular), hiperemia (congestão ativa) e necrose (caseosa, liquefativa, coagulativa).`},{id:`necr-110`,banca:`MAPA`,ano:2023,prova:`MAPA — Serviço Veterinário 2023`,tipo:`concurso`,topico:`diagnostico_necroscopico`,subtopico:`Diagnóstico de doenças de notificação obrigatória`,dificuldade:`dificil`,enunciado:`Ao suspeitar de doença de notificação obrigatória durante a necropsia, o médico veterinário deve:`,alternativas:[`Suspender a necropsia (se houver risco de contaminação), coletar material adequado para confirmação laboratorial, notificar imediatamente o serviço veterinário oficial (MAPA/CEVA), e adotar medidas de biossegurança.`,`Continuar a necropsia normalmente sem notificação.`,`Apenas emitir o laudo e arquivar.`,`Notificar apenas o proprietário do animal.`,`Aguardar o resultado laboratorial para notificar.`],resposta_correta:`A`,explicacao:`A notificação de doenças de notificação obrigatória (febre aftosa, peste suína, raiva, influenza aviária, entre outras) é obrigatória e imediata (Decreto-Lei nº 76.967/1976 — CENCI). O veterinário deve: coletar material diagnóstico, suspender procedimentos que possam disseminar o agente, notificar o serviço oficial (MAPA), e aplicar biossegurança.`},{id:`necr-111`,banca:`CRMV`,ano:2021,prova:`CRMV — Exame 2021`,tipo:`crmv`,topico:`diagnostico_necroscopico`,subtopico:`Interpretação de lesões hepáticas`,dificuldade:`medio`,enunciado:`As alterações hepáticas mais frequentemente observadas na necropsia e seu significado diagnóstico incluem:`,alternativas:[`Hepatomegalia congestiva (insuficiência cardíaca direita), fígado "em noz-moscada" (congestão passiva crônica), lipidose (obesidade, toxinas), necrose (viral, tóxica), e abscessos (piémia).`,`Apenas hepatomegalia.`,`Exclusivamente necrose hepática.`,`Apenas lipidose hepática.`,`Não há alterações hepáticas relevantes na necropsia.`],resposta_correta:`A`,explicacao:`As alterações hepáticas na necropsia incluem: hepatomegalia congestiva (ICD), fígado "em noz-moscada" (centro lobular congesto — ICD crônica), lipidose (gatos, bovinos, toxinas), necrose (viral — IBR, leptospirose; tóxica — plantas, micotoxinas), cirrose (crônica), abscessos (piémia, extensão de abomasite), e neoplasias (linfoma, carcinoma).`},{id:`necr-112`,banca:`USP`,ano:2022,prova:`USP — Concurso 2022`,tipo:`concurso`,topico:`diagnostico_necroscopico`,subtopico:`Limitações do diagnóstico necroscópico`,dificuldade:`medio`,enunciado:`Sobre as limitações do diagnóstico por necropsia, é correto afirmar:`,alternativas:[`O diagnóstico definitivo frequentemente requer exames complementares (histopatologia, bacteriologia, PCR), e em alguns casos, mesmo com todos os exames, a causa mortis pode permanecer indeterminada.`,`O diagnóstico macroscópico é sempre suficiente.`,`A necropsia nunca é capaz de determinar a causa da morte.`,`Os exames complementares sempre fornecem o diagnóstico definitivo.`,`A causa mortis é sempre evidente na necropsia.`],resposta_correta:`A`,explicacao:`O diagnóstico necroscópico tem limitações: 1) alterações autolíticas podem obscurecer lesões; 2) algumas doenças causam lesões sutis ou inespecíficas; 3) a macroscopia é insuficiente para diagnóstico etiológico em muitos casos; 4) exames complementares são frequentemente necessários; 5) mesmo com todos os exames, a causa mortis pode permanecer indeterminada.`},{id:`necr-113`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`biosseguranca_necropsia`,subtopico:`EPIs para necropsia`,dificuldade:`facil`,enunciado:`Os equipamentos de proteção individual (EPIs) obrigatórios para realização de necropsia incluem:`,alternativas:[`Luvas de procedimento (ou de nitrila/látex), avental impermeável, máscara (PFF2 ou N95 para aerossóculos), proteção ocular (óculos ou face shield), botas de borracha e touca/capacete.`,`Apenas luvas de procedimento.`,`Exclusivamente avental e luvas.`,`Apenas máscara cirúrgica comum.`,`Não é necessário uso de EPIs para necropsia.`],resposta_correta:`A`,explicacao:`Os EPIs para necropsia visam proteger contra riscos biológicos (zoonoses, aerossóis), químicos (formol, desinfetantes) e físicos (cortes, perfurações): luvas (preferencialmente nitrila, dupla para procedimentos de risco), avental impermeável, máscara PFF2/N95 (proteção respiratória contra aerossóculos), proteção ocular, botas de borracha e touca.`},{id:`necr-114`,banca:`CESPE`,ano:2022,prova:`CESPE — Veterinário 2022`,tipo:`concurso`,topico:`biosseguranca_necropsia`,subtopico:`Riscos biológicos na necropsia`,dificuldade:`medio`,enunciado:`Julgue o item sobre riscos biológicos na necropsia:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A necropsia expõe o profissional a diversos riscos biológicos, incluindo: zoonoses bacterianas (brucelose, leptospirose, tuberculose, antraz), virais (raiva, influenza aviária, COVID-19), fúngicas (blastomicose, coccidioidomicose) e parasitárias (equinococose, larva migrans). A exposição ocorre por contato com fluidos corporais, aerossóis, picadas e cortes acidentais.`,explicacao:`Os riscos biológicos na necropsia são múltiplos e incluem agentes de alta patogenicidade. A via de exposição mais frequente é a cutânea (mucosas, feridas), seguida da inalação (aerossóis gerados pelo corte com serras e instrumentos) e ingestão (contaminação acidental). O uso correto de EPIs e técnica asséptica minimiza os riscos.`},{id:`necr-115`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso 2021`,tipo:`concurso`,topico:`biosseguranca_necropsia`,subtopico:`Descarte de resíduos de necropsia`,dificuldade:`medio`,enunciado:`Os resíduos gerados pela necropsia (órgãos, tecidos, fluidos, EPIs contaminados) devem ser:`,alternativas:[`Classificados como resíduos biológicos (Grupo A — RGRS), acondicionados em sacos vermelhos, e destinados à incineração ou tratamento térmico prévio, conforme a RDC ANVISA nº 222/2018 e normas estaduais/municipais.`,`Descartados em lixo comum.`,`Enterrados no local da necropsia sem tratamento.`,`Descartados em sacos pretos de lixo domiciliar.`,`Lançados em corpos d'água após desinfecção.`],resposta_correta:`A`,explicacao:`Os resíduos de necropsia são classificados como resíduos biológicos (Grupo A1 — RGRS), potencialmente infectantes. Devem ser acondicionados em sacos vermelhos, etiquetados, e destinados a serviços de gerenciamento de resíduos de serviços de saúde (GRSS), preferencialmente por incineração. O descarte inadequado contamina o ambiente e pode disseminar doenças.`},{id:`necr-116`,banca:`UFMG`,ano:2020,prova:`UFMG — Concurso 2020`,tipo:`concurso`,topico:`biosseguranca_necropsia`,subtopico:`Desinfecção de instrumentos e local`,dificuldade:`medio`,enunciado:`Após a necropsia, os instrumentos e o local devem ser desinfetados com:`,alternativas:[`Lavagem dos instrumentos com água e sabão, seguida de desinfecção com hipoclorito de sódio a 2-5%, glutaraldeído a 2% ou álcool 70%. O local deve ser limpo e desinfetado com solução de hipoclorito ou fenol.`,`Apenas lavagem com água corrente.`,`Água sanitária doméstica pura.`,`Apenas secagem ao sol dos instrumentos.`,`Não é necessário desinfetar instrumentos ou local.`],resposta_correta:`A`,explicacao:`A desinfecção pós-necropsia é obrigatória: instrumentos devem ser lavados (remoção de material orgânico) e desinfetados (hipoclorito de sódio 2-5%, glutaraldeído 2%, álcool 70%, ou autoclavagem). O local deve ser limpo e desinfetado com solução de hipoclorito ou fenol. Resíduos sólidos devem ser incinerados. Esses procedimentos previnem a disseminação de agentes infecciosos.`},{id:`necr-117`,banca:`ENAV`,ano:2024,prova:`ENAV — Residência 2024`,tipo:`residencia`,topico:`biosseguranca_necropsia`,subtopico:`Necropsia de animais com suspeita de raiva`,dificuldade:`dificil`,enunciado:`Na necropsia de animal com suspeita de raiva, os cuidados de biossegurança incluem:`,alternativas:[`Utilização de EPIs completos (luvas dupla, avental impermeável, máscara N95, proteção ocular, face shield), coleta de encéfalo (tronco encefálico — hipocampo, cerebelo, bulbo), e encaminhamento ao laboratório oficial (LANAGRO/LACEN) em recipiente rígido e lacrado.`,`Necropsia completa sem precauções adicionais.`,`Apenas coleta de sangue periférico.`,`Não é possível necropsiar animais com suspeita de raiva.`,`Encaminhar o animal inteiro sem necropsia.`],resposta_correta:`A`,explicacao:`A raiva é zoonose fatal e de altíssimo risco. A necropsia requer biossegurança máxima: EPIs completos, preferencialmente em fluxo laminar ou cabine de segurança biológica. O material de escolha é o tronco encefálico (hipocampo, cerebelo, bulbo) para exame direto (IFD — imunofluorescência direta). O encéfalo deve ser enviado ao laboratório oficial em recipiente rígido, lacrado e refrigerado.`},{id:`necr-118`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário 2023`,tipo:`concurso`,topico:`biosseguranca_necropsia`,subtopico:`Necropsia em campo vs. laboratório`,dificuldade:`medio`,enunciado:`A necropsia realizada em campo apresenta riscos adicionais comparada à realizada em laboratório porque:`,alternativas:[`Em campo, há menor controle de ventilação, dificuldade de desinfecção adequada, exposição a insetos vetores, presença de animais domésticos e silvestres, e dificuldade de disposição adequada dos resíduos.`,`Em campo não há riscos adicionais.`,`Apenas a falta de equipamentos é o diferencial.`,`O risco é menor em campo por ser ambiente aberto.`,`A necropsia em campo é proibida por legislação.`],resposta_correta:`A`,explicacao:`A necropsia em campo apresenta riscos adicionais: ventilação inadequada (aerossóculos), contaminação do solo e água, atração de insetos e predadores, dificuldade de desinfecção e disposição de resíduos, exposição a condições climáticas adversas e presença de outros animais. Medidas de mitigação incluem posicionamento a favor do vento, uso de lonas e desinfetantes.`},{id:`necr-119`,banca:`CRMV`,ano:2023,prova:`CRMV — Exame 2023`,tipo:`crmv`,topico:`biosseguranca_necropsia`,subtopico:`Acidentes durante a necropsia`,dificuldade:`medio`,enunciado:`Em caso de acidente perfurocortante durante a necropsia (corte ou picada com instrumento contaminado), o profissional deve:`,alternativas:[`Lavar imediatamente o ferimento com água e sabão, comprimir para sangramento, aplicar antisséptico (PVPI ou clorexidina), e procurar atendimento médico para avaliação de profilaxia (vacinas, soroterapia) conforme o agente suspeito.`,`Ignorar o acidente e continuar o procedimento.`,`Apenas aplicar álcool no local.`,`Encerrar a necropsia sem qualquer cuidado adicional.`,`Apenas cobrir o ferimento com bandagem.`],resposta_correta:`A`,explicacao:`O acidente perfurocortante durante necropsia é emergência ocupacional. Protocolo: 1) lavar imediatamente com água e sabão; 2) comprimir para sangramento; 3) aplicar antisséptico; 4) procurar atendimento médico (Serviço de Referência em Riscos Ocupacionais); 5) avaliar necessidade de profilaxia (raiva — soro antirábico + vacina; tétano — toxoide tetânico; brucelose — acompanhamento sorológico).`},{id:`necr-120`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso 2020`,tipo:`concurso`,topico:`biosseguranca_necropsia`,subtopico:`Transporte de cadáveres para necropsia`,dificuldade:`medio`,enunciado:`O transporte de cadáveres de animais para realização de necropsia em laboratório deve seguir:`,alternativas:[`Acondicionamento em sacos impermeáveis duplos, etiquetagem com dados do animal e suspeita diagnóstica, transporte em veículo refrigerado ou com gelo, e comunicação prévia ao laboratório sobre a suspeita de doença de alto risco.`,`Transporte em veículo comum sem proteção.`,`Apenas acondicionamento em saco plástico simples.`,`Transporte sem etiquetagem.`,`Não há normas para transporte de cadáveres.`],resposta_correta:`A`,explicacao:`O transporte de cadáveres para necropsia requer: acondicionamento em sacos impermeáveis (duplo para maior segurança), etiquetagem com identificação completa (espécie, sexo, idade, data da morte, suspeita diagnóstica), cadeia de frio (refrigeração com gelo ou veículo refrigerado), veículo adequado (evitar contato com alimentos), e comunicação ao laboratório, especialmente em suspeita de doenças de alto risco.`},{id:`necr-121`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Concurso 2022`,tipo:`concurso`,topico:`biosseguranca_necropsia`,subtopico:`Necropsia de animais com suspeita de antraz`,dificuldade:`dificil`,enunciado:`Em caso de suspeita de antraz (Bacillus anthracis), o procedimento correto é:`,alternativas:[`NÃO realizar necropsia. O diagnóstico é feito por coleta de sangue periférico (veia jugular ou orelha) com seringa e agulha estéreis, sem abertura do cadáver. O animal deve ser incinerado in loco.`,`Realizar necropsia completa com EPIs.`,`Apenas abrir a cavidade abdominal.`,`Coletar fragmentos de baço com bisturi.`,`Aguardar 72 horas para a putrefação inativar o agente.`],resposta_correta:`A`,explicacao:`O antraz (Bacillus anthracis) é doença de notificação obrigatória e alto risco. A abertura do cadáver é PROIBIDA (libera esporos no ambiente, persistentes por décadas). O diagnóstico é feito por: coleta de sangue de veia periférica (veia jugular ou orelha) com agulha grossa, esfregaço sanguíneo (IFD, coloração de Gram — bacilos encapsulados em "tambor de lavanderia"), e cultura. O cadáver deve ser incinerado.`},{id:`necr-122`,banca:`MAPA`,ano:2024,prova:`MAPA — Serviço Veterinário 2024`,tipo:`concurso`,topico:`biosseguranca_necropsia`,subtopico:`Notificação de acidente ocupacional`,dificuldade:`facil`,enunciado:`O acidente ocupacional durante a necropsia (exposição a material biológico) deve ser:`,alternativas:[`Registrado em formulário de comunicação de acidente de trabalho (CAT), notificado ao serviço de segurança do trabalho, e acompanhado medicalmente, conforme a NR-6 e legislação trabalhista.`,`Ignorado se o profissional não apresentar sintomas imediatos.`,`Comunicado apenas verbalmente ao supervisor.`,`Documentado apenas no prontuário do paciente animal.`,`Não há obrigatoriedade de registro.`],resposta_correta:`A`,explicacao:`Acidentes ocupacionais com material biológico durante necropsia devem ser: 1) registrados em formulário de CAT (Comunicação de Acidente de Trabalho); 2) notificados ao serviço de segurança do trabalho; 3) acompanhados medicalmente (profilaxia, sorologias de acompanhamento). A NR-6 regulamenta os EPIs e a NR-32 regulamenta a segurança em serviços de saúde, incluindo laboratórios veterinários.`},{id:`necr-123`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Concurso 2023`,tipo:`concurso`,topico:`conceitos_necropsia`,subtopico:`Necropsia veterinária e One Health`,dificuldade:`medio`,enunciado:`A necropsia veterinária contribui para o conceito de One Health porque:`,alternativas:[`Permite a detecção de zoonoses, doenças emergentes e reemergentes, e patógenos de relevância para saúde pública, fornecendo dados para vigilância integrada animal-humano-ambiente.`,`Apenas para diagnóstico de doenças exclusivamente animais.`,`Não há relação entre necropsia veterinária e saúde humana.`,`A contribuição se limita à inspeção de produtos de origem animal.`,`One Health é um conceito exclusivamente médico-humano.`],resposta_correta:`A`,explicacao:`O conceito One Health reconhece a interconexão entre saúde animal, humana e ambiental. A necropsia veterinária é ferramenta-chave para: detecção de zoonoses emergentes (COVID-19, influenza aviária, Ebola), vigilância de resistência antimicrobiana, monitoramento de contaminação ambiental, e detecção de doenças de notificação internacional (WOAH).`},{id:`necr-124`,banca:`ENAV`,ano:2024,prova:`ENAV — Concurso 2024`,tipo:`concurso`,topico:`tecnica_necropsia_bovina`,subtopico:`Exame do sistema endócrino em bovino`,dificuldade:`dificil`,enunciado:`Na necropsia de bovino, o exame do sistema endócrino deve incluir:`,alternativas:[`Hipófise (localizada na sela túrcica), tireoide (peso, tamanho, consistência), paratireoides, adrenais (peso, relação córtex-medula) e pâncreas endócrino (ilhotas de Langerhans).`,`Apenas a tireoide e hipófise.`,`Exclusivamente as glândulas adrenais.`,`O sistema endócrino não é avaliado em necropsia de rotina.`,`Apenas a hipófise.`],resposta_correta:`A`,explicacao:`O sistema endócrino na necropsia bovina inclui: hipófise (adenomas em bovinos idosos), tireoide (hiperplasia, neoplasias), paratireoides (hiperparatireoidismo renal), adrenais (atrofia cortical, neoplasias) e pâncreas endócrino (diabetes mellitus é raro em bovinos). A avaliação do peso e relação córtex-medula das adrenais é importante.`},{id:`necr-125`,banca:`CESPE`,ano:2024,prova:`CESPE — Analista MAPA 2024`,tipo:`concurso`,topico:`processos_pre_mortem`,subtopico:`Avaliação do estresse pré-abate`,dificuldade:`medio`,enunciado:`Os indicadores de estresse pré-abate em bovinos incluem:`,alternativas:[`Taquipneia, vocalização excessiva, sudorese, queda, tentativas de fuga, cortisol plasmático elevado, e creatina quinase (CK) sérica elevada.`,`Apenas a frequência cardíaca elevada.`,`Exclusivamente a coloração das mucosas.`,`Apenas o peso corporal reduzido.`,`Não há indicadores confiáveis de estresse.`],resposta_correta:`A`,explicacao:`O estresse pré-abate é avaliado por indicadores comportamentais (vocalização, quedas, tentativas de fuga, congestão), fisiológicos (taquipneia, taquicardia, cortisol elevado) e bioquímicos (CK elevada por lesão muscular, lactato elevado, glicose elevada). O manejo adequado (Low Stress Handling) minimiza o estresse e melhora a qualidade da carne.`},{id:`necr-126`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`coleta_preservacao_material`,subtopico:`Coleta para diagnóstico molecular (PCR)`,dificuldade:`medio`,enunciado:`Para diagnóstico molecular (PCR) a partir de material de necropsia:`,alternativas:[`Fragmentos de tecido fresco devem ser coletados assepticamente, acondicionados em microtubos estéreis, e mantidos congelados (-20°C ou -70°C) até o processamento. A contaminação deve ser evitada rigorosamente.`,`O material deve ser fixado em formol a 10% antes da coleta.`,`Apenas sangue com anticoagulante é adequado para PCR.`,`Material em putrefação é ideal para PCR.`,`Não é necessário cuidado especial com a esterilidade.`],resposta_correta:`A`,explicacao:`O diagnóstico molecular (PCR) requer material com DNA/RNA íntegro: coleta asseptica, fragmentos frescos congelados (-20°C para DNA, -70°C para RNA), e processamento rápido. O formol degrada o DNA/RNA e interfere na PCR. A contaminação é o principal fator de resultado falso-positivo, exigindo instrumentos estéreis e descartáveis.`},{id:`necr-127`,banca:`UFMG`,ano:2024,prova:`UFMG — Concurso 2024`,tipo:`concurso`,topico:`diagnostico_necroscopico`,subtopico:`Lesões de deficiência nutricional`,dificuldade:`medio`,enunciado:`As lesões de necropsia sugestivas de deficiência nutricional incluem:`,alternativas:[`Raquitismo/osteomalácia (ossos moles, curvatura), degeneração muscular (doença do músculo branco — selênio/vit. E), lipidose hepática, anemia (ferro, cobre, vit. B12), e edema subcutâneo (hipoproteinemia).`,`Apenas emagrecimento progressivo.`,`Exclusivamente lesões ósseas.`,`Não há lesões macroscópicas de deficiência nutricional.`,`Apenas alterações de pelagem.`],resposta_correta:`A`,explicacao:`As deficiências nutricionais produzem lesões características: deficiência de vitamina D/cálcio/fósforo (raquitismo em jovens, osteomalácia em adultos), selênio/vitamina E (degeneração muscular — doença do músculo branco), cobre (anemia, degeneração do SNC em cordeiros), ferro (anemia hipocrômica em leitões), e proteínas (edema, ascite).`},{id:`necr-128`,banca:`MAPA`,ano:2024,prova:`MAPA — Serviço Veterinário 2024`,tipo:`concurso`,topico:`biosseguranca_necropsia`,subtopico:`Nível de biossegurança para necropsia`,dificuldade:`medio`,enunciado:`O nível de biossegurança recomendado para realização de necropsia de animais com doenças infectocontagiosas comuns é:`,alternativas:[`Biossegurança nível 2 (BSN-2), com EPIs adequados, bancada de trabalho descontaminável, e procedimentos de desinfecção padrão. Para agentes de alto risco (raiva, antraz), BSN-3 ou BSN-4 é necessário.`,`Biossegurança nível 1 (BSN-1) é suficiente para qualquer necropsia.`,`Não há classificação de níveis de biossegurança para necropsia.`,`Biossegurança nível 4 é obrigatória para todas as necropsias.`,`Apenas EPIs básicos são necessários.`],resposta_correta:`A`,explicacao:`A classificação de biossegurança (BSN-1 a BSN-4) é definida pelo CDC/NIH e adotada no Brasil. Para necropsia de rotina (doenças infectocontagiosas comuns), BSN-2 é adequado: EPIs, bancada descontaminável, procedimentos padrão. Para agentes de alto risco (raiva, antraz, febre hemorrágica), BSN-3 ou BSN-4 é necessário, com contenção adicional.`},{id:`necr-129`,banca:`ENAV`,ano:2024,prova:`ENAV — Residência 2024`,tipo:`residencia`,topico:`processos_post_mortem`,subtopico:`Congelamento e artefatos post mortem`,dificuldade:`medio`,enunciado:`O congelamento prévio do cadáver antes da necropsia:`,alternativas:[`Produz artefatos teciduais (cristais de gelo intracelulares e extracelulares) que dificultam a interpretação histológica, causando vacuolização, ruptura celular e perda de detalhes citoplasmáticos.`,`Melhora a qualidade da histopatologia.`,`Não afeta a interpretação das lesões.`,`É recomendado antes de todas as necropsias.`,`Apenas altera a coloração dos tecidos.`],resposta_correta:`A`,explicacao:`O congelamento de tecidos não criopreservados (sem DMSO ou glicerol) forma cristais de gelo que destroem a arquitetura celular, causando: vacuolização citoplasmática, ruptura de membranas, espaços artifactualmente criados, e perda de detalhes nucleares e citoplasmáticos. Esses artefatos dificultam ou impossibilitam a interpretação histopatológica.`},{id:`necr-130`,banca:`USP`,ano:2023,prova:`USP — Concurso 2023`,tipo:`concurso`,topico:`tecnica_necropsia_aviar`,subtopico:`Necropsia de aves para diagnóstico de Doença de Newcastle`,dificuldade:`dificil`,enunciado:`Para diagnóstico de Doença de Newcastle por necropsia, os achados característicos e a coleta adequada incluem:`,alternativas:[`Lesões hemorrágicas no trato gastrointestinal (proventrículo, intestino), edema e hemorragia em cabeça, coleta de swabs de cloaca e trato respiratório, e fragmentos de órgãos (intestino, encéfalo, rins) para PCR e isolamento viral.`,`Apenas lesões no sistema respiratório.`,`Exclusivamente alterações neurológicas.`,`Apenas swabs de orofaringe.`,`Não há lesões características na Doença de Newcastle.`],resposta_correta:`A`,explicacao:`A Doença de Newcastle (paramyxovirus aviário tipo 1) causa lesões hemorrágicas características no trato gastrointestinal (especialmente proventrículo e intestino), edema de cabeça e pescoço, e sinais neurológicos. Para diagnóstico: swabs de cloaca e trato respiratório, fragmentos de intestino, encéfalo e rins em meio de transporte viral, para PCR e isolamento em ovos embrionados.`},{id:`necr-131`,banca:`FCC`,ano:2024,prova:`FCC — Veterinário 2024`,tipo:`concurso`,topico:`tecnica_necropsia_canina_felina`,subtopico:`Necropsia de cães com suspeita de leishmaniose visceral`,dificuldade:`dificil`,enunciado:`Na necropsia de cães com suspeita de leishmaniose visceral (Leishmania infantum), os achados característicos incluem:`,alternativas:[`Linfadenomegalia generalizada, hepatoesplenomegalia, lesões cutâneas (alopecia, hiperqueratose, úlceras), glomerulonefrite, uveíte, e presença de amastigotas em macrófagos de linfonodos, baço, fígado e medula óssea.`,`Apenas lesões cutâneas.`,`Exclusivamente hepatoesplenomegalia.`,`Lesões pulmonares primárias.`,`Não há lesões macroscópicas características.`],resposta_correta:`A`,explicacao:`A leishmaniose visceral canina é doença sistêmica com múltiplas manifestações: linfadenomegalia, hepatoesplenomegalia, lesões cutâneas desfigurantes, glomerulonefrite (insuficiência renal), uveíte, artrite, e anemia. O diagnóstico é confirmado pela presença de amastigotas intracelulares em macrófagos (imuno-histoquímica, Giemsa) de múltiplos órgãos.`},{id:`necr-132`,banca:`UNESP`,ano:2023,prova:`UNESP — Concurso 2023`,tipo:`concurso`,topico:`tecnica_necropsia_suina`,subtopico:`Necropsia de suínos com PRRS`,dificuldade:`dificil`,enunciado:`Na necropsia de leitões afetados por PRRS (Síndrome Reprodutiva e Respiratória Suína), os achados incluem:`,alternativas:[`Pneumonia intersticial, linfonodos mediastínicos aumentados, edema pulmonar, e em reprodutores: abortos, natimortos e leitões mumificados. O diagnóstico é confirmado por PCR e sorologia.`,`Apenas pneumonia fibrinosa.`,`Exclusivamente lesões reprodutivas.`,`Lesões cutâneas características.`,`Não há lesões macroscópicas na PRRS.`],resposta_correta:`A`,explicacao:`O PRRS (Arterivirus suíno) causa pneumonia intersticial em leitões e distúrbios reprodutivos em matrizes (abortos, natimortos, natimortos mumificados, leitões fracos). Lesões macroscópicas são inespecíficas: pneumonia intersticial, linfonodos aumentados, edema pulmonar. O diagnóstico requer PCR (sangue, pulmão) e sorologia (ELISA).`},{id:`necr-133`,banca:`ENAV`,ano:2024,prova:`ENAV — Concurso 2024`,tipo:`concurso`,topico:`tecnica_necropsia_equina`,subtopico:`Necropsia de equinos com cólica`,dificuldade:`dificil`,enunciado:`Na necropsia de equino morto por cólica, os achados mais frequentes incluem:`,alternativas:[`Volvulo (torção intestinal), deslocamento do cólon dorsal, intussuscepção, impactação de ceco ou cólon, distensão gasosa, e necrose intestinal. O exame deve ser cuidadoso para não confundir achados post mortem com lesões ante mortem.`,`Apenas distensão gasosa do estômago.`,`Exclusivamente úlceras gástricas.`,`Não há alterações macroscópicas em casos de cólica.`,`Apenas parasitismo intestinal.`],resposta_correta:`A`,explicacao:`A cólica é a principal causa de morte em equinos. Na necropsia, os achados incluem: volvulo (torção do mesentério, cólon, ceco), deslocamento do cólon dorsal esquerdo ou direito, intussuscepção, impactação (areia, enterolitos), distensão gasosa, e necrose/hemorragia intestinal. É crucial diferenciar achados post mortem (autólise, distensão gasosa) de lesões ante mortem.`},{id:`necr-134`,banca:`CRMV`,ano:2022,prova:`CRMV — Exame 2022`,tipo:`crmv`,topico:`coleta_preservacao_material`,subtopico:`Coleta para micologia`,dificuldade:`medio`,enunciado:`Para diagnóstico de micoses na necropsia, a coleta de material deve incluir:`,alternativas:[`Fragmentos de lesões cutâneas (borda ativa), fragmentos de órgãos (pulmões em aspergilose, fígado em histoplasmose), raspados de pele (dermatofitose), e conteúdo de abscessos fúngicos, para cultura em Sabouraud e histopatologia (PAS, GMS).`,`Apenas raspados de pele.`,`Exclusivamente cultura bacteriológica.`,`Apenas fragmentos fixados em formol.`,`Material de animais vivos apenas.`],resposta_correta:`A`,explicacao:`O diagnóstico de micoses na necropsia requer: fragmentos de lesões cutâneas (borda ativa — onde o fungo é mais viável), fragmentos de órgãos profundos (pulmões — aspergilose, blastomicose; fígado, baço — histoplasmose; SNC — criptococose), raspados de pele (dermatofitose), e conteúdo de abscessos fúngicos. Cultura em Sabouraud e histopatologia (PAS, GMS) são complementares.`},{id:`necr-135`,banca:`AVAMEC`,ano:2024,prova:`AVAMEC — Concurso 2024`,tipo:`concurso`,topico:`biosseguranca_necropsia`,subtopico:`Transporte de material biológico de alto risco`,dificuldade:`medio`,enunciado:`O transporte de material biológico de alto risco (suspeita de raiva, antraz, influenza aviária altamente patogênica) deve seguir:`,alternativas:[`Normas da OMS para transporte de material infeccioso (UN 2814 ou UN 2900), com embalagem tríplice (recipiente primário estanque, embalagem secundária absorvente, embalagem externa rótulada), cadeia de frio e documentação adequada.`,`Apenas acondicionamento em saco plástico comum.`,`Transporte sem documentação especial.`,`Não há normas específicas para transporte de material de alto risco.`,`Enviar por correios convencionais.`],resposta_correta:`A`,explicacao:`O transporte de material infeccioso segue regulamentação internacional (OMS, IATA): embalagem tríplice (recipiente primário vedado, material absorvente, embalagem externa rígida com rótulo de risco biológico — UN 2814 para infectante para humanos ou UN 2900 para infectante apenas para animais). No Brasil, a ANVISA e ANTT regulamentam o transporte.`},{id:`necr-136`,banca:`MAPA`,ano:2020,prova:`MAPA — Serviço Veterinário 2020`,tipo:`concurso`,topico:`tecnica_necropsia_bovina`,subtopico:`Exame de carcaça no abatedouro`,dificuldade:`medio`,enunciado:`O exame post mortem de carcaças bovinas no abatedouro (inspeção post mortem) difere da necropsia clínica porque:`,alternativas:[`É focado na aptidão da carcaça para consumo humano, avaliando órgãos e tecidos para alterações que comprometam a segurança alimentar, enquanto a necropsia clínica visa determinar a causa mortis e o diagnóstico de doenças.`,`É idêntico à necropsia clínica.`,`Avalia apenas a aparência externa da carcaça.`,`Não requer conhecimento de patologia.`,`É realizado apenas por auxiliares de inspeção.`],resposta_correta:`A`,explicacao:`A inspeção post mortem em abatedouro é regulamentada pelo MAPA (RIISPOA) e foca na segurança alimentar: avaliação de carcaça, órgãos, vísceras e linfonodos para alterações (inflamação, neoplasia, parasitoses, contaminação). A necropsia clínica é mais ampla, incluindo exame de todos os sistemas e busca pela causa mortis.`},{id:`necr-137`,banca:`ENAV`,ano:2025,prova:`ENAV — Concurso 2025`,tipo:`concurso`,topico:`processos_post_mortem`,subtopico:`Fenômenos cadavéricos e temperatura`,dificuldade:`medio`,enunciado:`Em regiões tropicais (temperatura ambiente >30°C), os fenômenos cadavéricos ocorrem mais rapidamente porque:`,alternativas:[`O calor acelera as reações enzimáticas da autólise e o crescimento bacteriano da putrefação, reduzindo significativamente o tempo para início e progressão dos fenômenos cadavéricos.`,`O calor retarda a autólise.`,`A putrefação é inibida em altas temperaturas.`,`O rigor mortis dura mais tempo em climas quentes.`,`Não há influência da temperatura nos fenômenos cadavéricos.`],resposta_correta:`A`,explicacao:`A temperatura é o fator mais importante que modula a velocidade dos fenômenos cadavéricos. Em climas tropicais (>30°C), a autólise inicia em minutos, a putrefação em horas, e o rigor mortis é mais breve (duração reduzida). Em climas frios (<10°C), os processos são significativamente retardados. Isso é fundamental para a interpretação temporal dos achados de necropsia.`},{id:`necr-138`,banca:`CESPE`,ano:2024,prova:`CESPE — Veterinário MAPA 2024`,tipo:`concurso`,topico:`coleta_preservacao_material`,subtopico:`Cadeia de custódia de amostras`,dificuldade:`medio`,enunciado:`A cadeia de custódia de amostras de necropsia é importante porque:`,alternativas:[`Garante a rastreabilidade e integridade do material desde a coleta até o resultado laboratorial, sendo essencial para validação de laudos, investigações epidemiológicas e procedimentos legais.`,`Apenas para fins administrativos do laboratório.`,`Não tem relevância para o diagnóstico.`,`É obrigatória apenas em casos judiciais.`,`Apenas para controle de qualidade interno do laboratório.`],resposta_correta:`A`,explicacao:`A cadeia de custódia documenta: quem coletou, quando, como foi acondicionado, transportado, recebido e processado. É essencial para: validação de resultados (garantir que a amostra não foi trocada ou contaminada), investigações epidemiológicas (rastreabilidade), procedimentos legais (valor probatório) e auditorias.`},{id:`necr-139`,banca:`UFRRJ`,ano:2024,prova:`UFRRJ — Concurso 2024`,tipo:`concurso`,topico:`diagnostico_necroscopico`,subtopico:`Diagnóstico de intoxicações por necropsia`,dificuldade:`dificil`,enunciado:`O diagnóstico de intoxicações por necropsia é desafiador porque:`,alternativas:[`Muitos tóxicos não produzem lesões macroscópicas específicas, os efeitos são dose-dependentes, e a análise toxicológica requer amostras não fixadas em formol e processamento em laboratório especializado.`,`As intoxicações sempre produzem lesões evidentes.`,`O diagnóstico de intoxicação é sempre clínico, nunca necroscópico.`,`Não existem laboratórios para análise toxicológica veterinária.`,`Apenas plantas tóxicas podem ser diagnosticadas por necropsia.`],resposta_correta:`A`,explicacao:`O diagnóstico de intoxicações por necropsia é complexo: muitos tóxicos (organofosforados, metaldeído) não causam lesões específicas; as lesões são inespecíficas (necrose hepática, renal, hemorragias); a confirmação requer análise química de tecidos e fluidos em laboratório especializado; e as amostras NÃO devem ser fixadas em formol (interfere na análise).`},{id:`necr-140`,banca:`VUNESP`,ano:2024,prova:`VUNESP — Concurso 2024`,tipo:`concurso`,topico:`tecnica_necropsia_peixes`,subtopico:`Necropsia de peixes para diagnóstico de doenças infecciosas em aquicultura`,dificuldade:`medio`,enunciado:`Em surtos de mortalidade em piscicultura, a necropsia deve ser realizada:`,alternativas:[`Em pelo menos 5 a 10 peixes vivos ou recém-mortos, com sinais clínicos variados, para obtenção de amostras representativas e diagnóstico adequado do agente causador.`,`Apenas em peixes mortos há mais de 24 horas.`,`Exclusivamente em peixes congelados.`,`Não é necessário necropsiar peixes em surtos.`,`Apenas 1 peixe por tanque é suficiente.`],resposta_correta:`A`,explicacao:`Para diagnóstico em surtos de mortalidade em piscicultura, a necropsia deve ser realizada em peixes vivos ou recém-mortos (a autólise em peixes é rápida devido à temperatura da água e microbiota abundante). Recomenda-se 5 a 10 peixes com diferentes estágios da doença. O exame deve incluir bacteriologia, parasitologia, virologia e histopatologia.`},{id:`necr-141`,banca:`UFMG`,ano:2021,prova:`UFMG — Concurso 2021`,tipo:`concurso`,topico:`conceitos_necropsia`,subtopico:`Necropsia e medicina veterinária forense`,dificuldade:`medio`,enunciado:`A medicina veterinária forense utiliza a necropsia para:`,alternativas:[`Investigação de maus-tratos animais, envenenamento, morte por negligência, causas de morte em acidentes, e fornecimento de provas periciais para o sistema de justiça.`,`Apenas determinação de idade do animal.`,`Exclusivamente para avaliação de animais de produção.`,`Não há aplicação forense da necropsia veterinária.`,`Apenas para fins acadêmicos.`],resposta_correta:`A`,explicacao:`A medicina veterinária forense aplica conhecimentos de necropsia em investigações legais: maus-tratos (identificação de lesões crônicas, fraturas em diferentes estágios), envenenamento (coleta para toxicologia), morte por negligência (inanidade, desidratação), e acidentes (determinação de causa e mecanismo de morte). O laudo pericial tem valor probatório no judiciário.`},{id:`necr-142`,banca:`ENAV`,ano:2025,prova:`ENAV — Residência 2025`,tipo:`residencia`,topico:`processos_pre_mortem`,subtopico:`Bem-estar animal e manejo pré-abate em aves`,dificuldade:`medio`,enunciado:`O manejo pré-abate em frangos de corte inclui:`,alternativas:[`Jejum alimentar de 6-12 horas, retirada de comedouros, iluminação reduzida para diminuir estresse, captura cuidadosa (evitar fraturas e hematomas), transporte em caixotes ventilados com densidade adequada, e descanso no abatedouro.`,`Jejum de 48 horas antes do abate.`,`Captura mecânica sem cuidados especiais.`,`Transporte sem ventilação.`,`Não é necessário jejum em aves.`],resposta_correta:`A`,explicacao:`O manejo pré-abate em aves segue normas do MAPA e de bem-estar: jejum alimentar (6-12h — esvaziamento do trato gastrointestinal), acesso à água, iluminação reduzida (menos estresse), captura cuidadosa (evitar fraturas de asa e hematomas), transporte em caixotes ventilados com densidade adequada (máx. 40 kg/m²), e descanso no abatedouro (mín. 2h).`},{id:`necr-143`,banca:`CESPE`,ano:2023,prova:`CESPE — Analista MAPA 2023`,tipo:`concurso`,topico:`biosseguranca_necropsia`,subtopico:`Necropsia de animais silvestres`,dificuldade:`medio`,enunciado:`A necropsia de animais silvestres apresenta riscos adicionais porque:`,alternativas:[`Animais silvestres podem ser portadores de zoonoses emergentes (hantavírus, leptospirose, raiva), podem ser provenientes de tráfico ilegal (riscos legais), e a identificação da espécie pode ser difícil, exigindo conhecimento de anatomia comparada.`,`Animais silvestres não apresentam riscos adicionais.`,`O único risco é a mordida do animal.`,`Apenas animais domésticos transmitem zoonoses.`,`A necropsia de silvestres é proibida por lei.`],resposta_correta:`A`,explicacao:`A necropsia de animais silvestres requer: conhecimento de anatomia comparada (variação interespecífica), cautela com zoonoses (hantavírus em roedores, raiva em morcegos, leptospirose em diversas espécies), atenção à legislação ambiental (IBAMA, SISBIO — tráfico ilegal, fauna protegida), e biossegurança adequada para agentes desconhecidos.`},{id:`necr-144`,banca:`FCC`,ano:2024,prova:`FCC — Analista MAPA 2024`,tipo:`concurso`,topico:`processos_pre_mortem`,subtopico:`Inspeção ante-mortem de suínos`,dificuldade:`medio`,enunciado:`Na inspeção ante-mortem de suínos no abatedouro, além da avaliação clínica, deve-se verificar:`,alternativas:[`Identificação individual (marca/tatuagem), documentação sanitária (nota fiscal, Gta/GTV), período de carência de medicamentos, e procedência do lote para rastreabilidade.`,`Apenas o peso vivo dos animais.`,`Exclusivamente a temperatura retal.`,`Apenas a identificação por brinco.`,`Não é necessária documentação sanitária.`],resposta_correta:`A`,explicacao:`A inspeção ante-mortem de suínos inclui: avaliação clínica (estado geral, sinais de doença, marcha), verificação de documentação (nota fiscal, GTA/GTV — Guia de Trânsito Animal), identificação (brinco, tatuagem), período de carência (medicamentos), e procedência (rastreabilidade — SISBOV para bovinos, sistemas de identificação para suínos).`},{id:`necr-145`,banca:`UNESP`,ano:2024,prova:`UNESP — Concurso 2024`,tipo:`concurso`,topico:`diagnostico_necroscopico`,subtopico:`Diagnóstico de sepse na necropsia`,dificuldade:`dificil`,enunciado:`O diagnóstico de sepse (infecção sistêmica) na necropsia é baseado em:`,alternativas:[`Presença de foco infeccioso primário (pneumonia, peritonite, pielonefrite), disseminação hematogênica (abscessos em múltiplos órgãos), lesões vasculares (trombose, vasculite), e evidência de resposta inflamatória sistêmica (esplenomegalia, linfadenomegalia).`,`Apenas febre documentada antes da morte.`,`Exclusivamente cultura bacteriana positiva.`,`Apenas leucocitose no hemograma post mortem.`,`Não é possível diagnosticar sepse por necropsia.`],resposta_correta:`A`,explicacao:`O diagnóstico de sepse na necropsia requer: 1) identificação do foco infeccioso primário; 2) evidência de disseminação (abscessos metastáticos em rins, fígado, pulmões, cérebro); 3) lesões vasculares (tromboflebite, vasculite, infartos sépticos); 4) resposta sistêmica (esplenite, linfadenite, congestão generalizada). A cultura bacteriana de sangue post mortem pode ser positiva.`},{id:`necr-146`,banca:`CRMV`,ano:2024,prova:`CRMV — Exame 2024`,tipo:`crmv`,topico:`conceitos_necropsia`,subtopico:`Necropsia digital e telemedicina`,dificuldade:`medio`,enunciado:`A telemedicina aplicada à necropsia veterinária permite:`,alternativas:[`Acompanhamento remoto do procedimento por especialista, transmissão de imagens e vídeos em tempo real para consultoria, e segunda opinião de patologistas a distância, facilitando diagnósticos em áreas remotas.`,`A substituição completa da necropsia presencial.`,`Apenas a emissão de laudos sem exame do cadáver.`,`Não há aplicação de telemedicina em necropsia.`,`Apenas a gravação de vídeos para fins didáticos.`],resposta_correta:`A`,explicacao:`A telemedicina veterinária aplicada à necropsia é uma ferramenta emergente: permite consultoria remota em tempo real (especialista orienta a necropsia à distância), compartilhamento de imagens de alta resolução para segunda opinião, e acesso a patologistas em áreas onde não há especialistas disponíveis. Não substitui o procedimento presencial, mas o complementa.`},{id:`necr-147`,banca:`AVAMEC`,ano:2025,prova:`AVAMEC — Concurso 2025`,tipo:`concurso`,topico:`coleta_preservacao_material`,subtopico:`Biobanco e arquivamento de material de necropsia`,dificuldade:`medio`,enunciado:`O arquivamento adequado de material de necropsia (biobanco) inclui:`,alternativas:[`Organização de blocos de parafina (histopatologia), lâminas histológicas catalogadas, amostras congeladas (-80°C) para estudos futuros, fotodocumentação digital, e sistema de indexação por caso, espécie, diagnóstico e data.`,`Apenas arquivo dos laudos em papel.`,`Descarte de todo o material após o laudo.`,`Apenas fotografia digital dos órgãos.`,`Não é necessário arquivamento de material de necropsia.`],resposta_correta:`A`,explicacao:`O biobanco de necropsia é recurso valioso para: ensino (casos para aulas), pesquisa (revisão de casos, estudos retrospectivos), controle de qualidade (revisão diagnóstica), e vigilância epidemiológica (análise de tendências). Deve incluir: blocos de parafina, lâminas coradas, amostras congeladas (-80°C), fotodocumentação digital, e sistema de indexação.`},{id:`necr-148`,banca:`USP`,ano:2024,prova:`USP — Concurso 2024`,tipo:`concurso`,topico:`biosseguranca_necropsia`,subtopico:`Necropsia em tempos de pandemia`,dificuldade:`dificil`,enunciado:`Durante pandemias (ex: COVID-19), a necropsia de animais suspeitos de serem reservatórios ou transmissores requer:`,alternativas:[`Biossegurança nível 3 (BSN-3) ou superior, com fluxo de ar controlado, EPIs de alta proteção (PAPR ou N95 + face shield), protocolos de descontaminação rigorosos, e coordenação com autoridades de saúde pública.`,`Nenhuma medida adicional de biossegurança.`,`Apenas a necropsia deve ser evitada.`,`Biossegurança nível 1 é suficiente.`,`Apenas EPIs básicos (luvas e máscara cirúrgica).`],resposta_correta:`A`,explicacao:`Em pandemias, zoonoses emergentes (COVID-19, influenza aviária H5N1, Ebola) requerem biossegurança máxima para necropsia de animais suspeitos: BSN-3 ou superior, com fluxo de ar HEPA, EPIs de alta proteção (PAPR — Powered Air Purifying Respirator), protocolos rigorosos de descontaminação, e notificação imediata às autoridades de saúde pública (vigilância integrada One Health).`},{id:`necr-149`,banca:`MAPA`,ano:2025,prova:`MAPA — Serviço Veterinário 2025`,tipo:`concurso`,topico:`diagnostico_necroscopico`,subtopico:`Diagnóstico de morte súbita em bovinos`,dificuldade:`dificil`,enunciado:`O diagnóstico diferencial de morte súbita em bovinos adultos inclui:`,alternativas:[`Carbúnculo hemático (Anthrax), clostridioses (edema maligno, gangrena gasosa), intoxicação por plantas (Palicourea marcgravii, Amorimia exotropia), pneumoenterite bovina, timpanismo, e eletrocussão (raio).`,`Apenas infarto agudo do miocárdio.`,`Exclusivamente intoxicações por agrotóxicos.`,`Não há causas de morte súbita em bovinos.`,`Apenas carbúnculo hemático.`],resposta_correta:`A`,explicacao:`A morte súbita em bovinos tem amplo diagnóstico diferencial: carbúnculo hemático (Bacillus anthracis — baço aumentado, sangue incoagulável), clostridioses (edema maligno, gangrena gasosa — enfisema subcutâneo), intoxicações por plantas (Palicourea, Amorimia — "tingui"), timpanismo ruminal, pneumoenterite bovina, e eletrocussão por raio (lesões cutâneas características).`},{id:`necr-150`,banca:`ENAV`,ano:2025,prova:`ENAV — Concurso 2025`,tipo:`concurso`,topico:`conceitos_necropsia`,subtopico:`Futuro da necropsia veterinária`,dificuldade:`medio`,enunciado:`As tendências modernas em necropsia veterinária incluem:`,alternativas:[`Necropsia virtual (TC e RM post mortem), diagnóstico molecular avançado (NGS, metagenômica), telemedicina aplicada, inteligência artificial para análise de imagens histológicas, e integração com vigilância epidemiológica digital.`,`Apenas a substituição total por exames laboratoriais.`,`O desaparecimento da necropsia como ferramenta diagnóstica.`,`Apenas a digitalização dos laudos em papel.`,`A necropsia não sofreu avanços significativos nas últimas décadas.`],resposta_correta:`A`,explicacao:`A necropsia veterinária está em evolução: necropsia virtual (imagem post mortem por TC/RM), diagnóstico molecular de próxima geração (NGS para identificação de patógenos desconhecidos), telemedicina (consultoria remota), inteligência artificial (análise automatizada de imagens histológicas), biobancos digitais, e integração com plataformas de vigilância epidemiológica digital.`}],i={total_questoes:150,por_topico:{conceitos_necropsia:12,tecnica_necropsia_bovina:12,tecnica_necropsia_equina:9,tecnica_necropsia_canina_felina:11,tecnica_necropsia_suina:9,tecnica_necropsia_aviar:10,tecnica_necropsia_peixes:10,processos_pre_mortem:10,processos_post_mortem:11,coleta_preservacao_material:10,diagnostico_necroscopico:10,biosseguranca_necropsia:10},por_dificuldade:{facil:28,medio:78,dificil:44},por_banca:{ENAV:24,CESPE:14,FCC:14,VUNESP:14,AVAMEC:12,CRMV:10,UFMG:14,UNESP:12,USP:10,UFRRJ:8,MAPA:14},por_tipo:{concurso:120,residencia:18,crmv:8,enav:0,pos:0},atualizado_em:`2025-01-15`};export{e as BANCAS,i as ESTATISTICAS_BANCO,r as QUESTOES_NECROPSIA,t as TIPOS_PROVA,n as TOPICOS_NECROPSIA};